    ["Local AI switched to {model}: the game is using most of your graphics memory."] = "Local AI переключился на {model}: игра использует большую часть видеопамяти.",
    ["Choose one of the listed Local AI models."] = "Выберите одну из перечисленных моделей Local AI.",
    ["Characters to invite"] = "Персонажи для приглашения",
    ["Whose memories"] = "Чьи воспоминания",
    ["Invalid Mature content settings."] = "Недопустимые настройки контента для взрослых.",
    ["Your message was not sent. Open the text box again and retype it."] = "Ваше сообщение не отправлено. Откройте текстовое поле снова и введите его ещё раз.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Недоступны: {models}. См. заметки о Local AI, раздел «Добавление своей модели».",
    ["an embedding model, not a chat model"] = "модель эмбеддингов, а не чат-модель",
    ["could not be read"] = "не удалось прочитать",
    ["file not found"] = "файл не найден",
    ["not a valid GGUF file"] = "не является допустимым файлом GGUF",
    ["{name} (custom)"] = "{name} (пользовательская)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Подготовка {name}: ожидание подключения службы бесед…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Подготовка {name}: ожидание загрузки голосовой модели…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Подготовка {name}: ожидание открытия соединения для бесед…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Подготовка {name}: ожидание, пока игра разместит персонажа…",
    ["Preparing {name}: waiting for the memory service…"] = "Подготовка {name}: ожидание службы памяти…",
    ["Preparing {count} more companions…"] = "Подготовка остальных напарников: {count}…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "Служба бесед не ответила. Подождите немного и пригласите снова.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "Голосовую модель не удалось загрузить. Проверьте голос в настройках или выберите другой и пригласите снова.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Служба памяти не ответила. Проверьте подключение и пригласите снова.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "Соединение для бесед не открылось. Проверьте подключение и пригласите снова.",
    ["Convai sign-in is busy right now. Wait a few minutes, then invite again."] = "Вход в Convai сейчас занят. Подождите несколько минут и пригласите снова.",
    ["The Convai daily limit is used up. Choose another provider in Settings, or invite again tomorrow."] = "Дневной лимит Convai исчерпан. Выберите другого поставщика в настройках или пригласите снова завтра.",
    ["Calls are not available during combat."] = "Звонки недоступны во время боя.",
    ["Calls are not available right now."] = "Звонки сейчас недоступны.",
    ["Holocall ended: combat started."] = "Голозвонок завершён: начался бой.",
    ["Holocall with {name} ended."] = "Голозвонок с {name} завершён.",
    ["Live picture unavailable. The call continues with the portrait."] = "Живое изображение недоступно. Звонок продолжится с портретом.",
    ["This contact cannot take a holocall."] = "Этот контакт не может принять голозвонок.",
    ["You are already on a call."] = "Вы уже в звонке.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "Когда начинается бой, ближайший напарник коротко комментирует, и ещё раз — после него.\n\nПосле боя — десятиминутная пауза. Разговоры и сюжетные сцены важнее. Загрузка сохранения сбрасывает паузу.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Попросите напарника отвезти вас к выбранной на карте метке.\n\nСядьте на пассажирское место, когда он будет готов.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Авто: следует за завершённой встречей в этом сохранении.\n\nДружеский: говорит с такой же близостью.\n\nОбычный: сохраняет её привычную манеру.\n\nЭто не значит, что отношения продолжаются.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Авто: следует за отношениями в этом сохранении.\n\nРомантический: обращается к V как к партнёру.\n\nОбычный: сохраняет свою привычную манеру.\n\nМеняет только манеру речи, но не игровые решения.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "Звук по Bluetooth приходит с небольшой задержкой, поэтому губы и субтитры могут опережать голос. Эта настройка придерживает их, чтобы совпасть с голосом, для всех голосов.\n\nАвто: 150 мс, пока Windows воспроизводит звук через Bluetooth, иначе ничего. Выберите значение, если ваша гарнитура быстрее или медленнее.\n\nВ собственных репликах игры такая же задержка, и она не исправляется.",
    ["Characters sometimes ask about something you said, pick up something from earlier or share a thought that invites an answer.\n\nNow and then, never on every reply, and never while you are leaving, giving an order or fighting."] = "Персонажи иногда спрашивают о том, что вы сказали, вспоминают что-то из прошлого или делятся мыслью, на которую хочется ответить.\n\nИзредка, не в каждом ответе, и никогда, пока вы уходите, отдаёте приказ или сражаетесь.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "История чата сохраняется между запусками игры.\n\nУдаление воспоминаний о персонаже также удаляет его сохранённые сообщения чата и черновики. Удаление всех воспоминаний очищает все сохранённые чаты.",
    ["Cinematic: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nThe Subtitles switch turns both off."] = "Кинематографические: обычные субтитры диалогов игры.\n\nНад говорящим: над напарником, который говорит.\n\nПереключатель «Субтитры» отключает оба варианта.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "Напарники комментируют, когда вы закончили собирать добычу в мире. Перемещения в хранилище проходят без комментариев.\n\nОбычные комментарии появляются раз в десять минут; новое легендарное снаряжение имеет собственную двухминутную паузу.\n\nПодборы во время боя объединяются в один комментарий в конце боя.",
    ["Custom models are ones you added; they join the default choice by size."] = "Добавленные вами модели участвуют в выборе по умолчанию по размеру.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Только глаза: голова неподвижна, двигаются только глаза.\n\nОт слабого до сильного: голова всё больше поворачивается к вам.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "«Удалить все воспоминания» применяется к этим персонажам.\n\nПросмотр каталога или приглашение напарника не добавляет никого в этот счётчик.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "Члены банд, полицейские NCPD, охранники, рипердоки, продавцы, бармены и прохожие отвечают в духе своей среды.\n\nОни не знают вашей истории и забывают вас после загрузки сохранения, кроме продавцов, к которым вы возвращаетесь.\n\nИменованные персонажи не затрагиваются.",
    ["Talk to story characters"] = "Разговоры с персонажами сюжета",
    ["{name} is busy right now."] = "{name} сейчас не может говорить.",
    ["{name} is not in your head right now."] = "{name} сейчас не в вашей голове.",
    ["{name} is a story character. Turn on Talk to story characters in Esc > Mods."] = "{name}: включите «Разговоры с персонажами сюжета» в Esc > Mods.",
    ["Talk to ordinary NPCs is off. Turn it on in Esc > Mods."] = "Разговоры с обычными NPC выключены. Включите их в Esc > Mods.",
    ["{name} is a child and cannot be talked to."] = "С {name} нельзя поговорить: это ребёнок.",
    ["{name} is not a person and cannot be talked to."] = "С {name} нельзя поговорить: это не человек.",
    ["{name} cannot be talked to: the mod cannot tell which voice fits."] = "С {name} нельзя поговорить: мод не может определить, какой голос подходит.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Если персонаж перестаёт отвечать, голос пропадает или появляется ошибка: выберите «Сформировать отчёт» и отправьте разработчику указанный в нём файл с кратким описанием того, что вы делали.\n\nЖурналы, перечисленные ниже, показывают, что пошло не так.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Приглашённые персонажи готовятся сразу. Их воспоминания начинаются, когда вы действительно заговорите с ними.\n\nОдна личность игрока используется во всех сохранениях и не меняется после удаления воспоминаний.\n\nТекущий контекст игры описывает загруженный мир.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Найдены только модели для взрослых. Включите Контент для взрослых.",
    ["Something on this PC (a firewall or security software) is blocking the connection to the model server you added."] = "Что-то на этом ПК (брандмауэр или программа безопасности) блокирует подключение к серверу модели, который вы добавили.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Нельзя: секс с несовершеннолетними, без согласия, о реальных людях, ненависть, инструкции по оружию и наркотикам. Запрет для детей проверяется.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Выкл.: ответы только текстом, голос не создаётся.\n\nЕсли выключены и субтитры, автоматические реакции остаются без звука.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Посмотрите, что помнит каждый персонаж, и сотрите воспоминания одного или всех.\n\nВоспоминания сохраняются между сохранениями.",
    ["Shows companion replies as text.\n\nWith Voice playback off as well, automatic reactions stay silent."] = "Показывает ответы напарников текстом.\n\nЕсли озвучивание ответов тоже выключено, автоматические реакции остаются без звука.",
    ["Voxtral · not with Mature"] = "Voxtral · без контента 18+",
    ["Voxtral is not used with Mature content."] = "Voxtral не используется с контентом для взрослых.",
    ["Needs Local AI or Custom."] = "Нужен Local AI или Свой.",
    ["Mature content is turned off because you chose a model that is not a Mature model."] = "Контент для взрослых выключен, потому что выбрана модель, которая не для взрослых.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "Нецензурная лексика, жестокость, наркотики и, между взрослыми по согласию, флирт и секс. Только 18+, нужен Local AI или Свой.",
    ["From Convai or Mistral, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "С Convai или Mistral включение выбирает Local AI, а если Local AI не установлен, то Свой. С Local AI также выбирается самая большая подходящая модель без цензуры. Выключение возвращает ваши настройки.",
    ["Choosing Convai or Mistral turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Выбор Convai или Mistral выключает её. С ней Voxtral не используется: голос Voxtral переходит на Pocket и возвращается, когда её выключают.",
    ["Use it if companions seem to look above or below your eyes."] = "Включите, если напарники как будто смотрят выше или ниже ваших глаз.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Облако Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · нужен ключ Mistral",
    ["{name} (custom · too large)"] = "{name} (пользовательская · велика)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (своя, {size} ГБ, нужно {need} ГБ)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (пользовательская, {size} ГБ, слишком велика для видеокарты)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Удалить воспоминания о вас у всех персонажей, с которыми вы общались.\n\nВаш идентификатор игрока сохранится. Сначала — подтверждение.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Сохраните файл отчёта, который можно отправить разработчику.\n\nКлючи API, токены, идентификаторы, звук с микрофона и текст бесед не включаются. Без службы бесед создаётся более короткий отчёт из файлов, которые может прочитать игра.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "Модели без цензуры из Mature pack (для Local AI) дают полный эффект; обычные чаще отказывают в сексе. Пакет: установлен.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Модели без цензуры из Mature pack (для Local AI) дают полный эффект; обычные чаще отказывают в сексе. Пакет: не установлен (необязательно, страница мода на Hugging Face).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Без выбора Local AI грузит самую большую модель, что влезет в видеопамять.\n\nОдна модель за раз; смена при следующей загрузке. Пропавшая, слишком большая или сбойная модель заменяется самой большой подходящей, с уведомлением.",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai не принял ваш API-ключ. Проверьте его в меню Настройки > Поставщик бесед.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Local AI не удалось запустить. Проверьте Local AI в меню Настройки > Поставщик бесед.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral не принял ваш ключ. Проверьте его в меню Настройки > Поставщик бесед.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Ключа Mistral пока нет, поэтому используется Convai. Добавьте свой ключ в меню Настройки > Поставщик бесед.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Нужен ключ Mistral (добавьте его в Настройки > Поставщик бесед)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Для бесед с напарниками пока нужен Convai. Установите в строке Поставщик бесед значение Convai (бесплатный тариф) в меню Настройки > Поставщик бесед или введите сообщение вручную.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider."] = "Достигнут лимит бесед. Попробуйте позже или добавьте бесплатный ключ Mistral и выберите Mistral как поставщика бесед в меню Настройки > Поставщик бесед.",
    ["Convai could not sign in. Try again in a moment, or choose Mistral or Local AI in Settings > Conversation provider."] = "Не удалось войти в Convai. Попробуйте через некоторое время или выберите Mistral либо Local AI в меню Настройки > Поставщик бесед.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Ваш API-ключ Convai достиг лимита тарифа. Попробуйте позже или добавьте другой ключ в меню Настройки > Поставщик бесед.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Mistral (free, with your own free key) allows about 5,000 turns a day. Local AI is unlimited and runs on your PC."] = "Вы исчерпали сегодняшний бесплатный лимит Convai. Он обновится завтра. Чтобы продолжить прямо сейчас, выберите другого поставщика бесед в меню Настройки > Поставщик бесед. Mistral (бесплатно, с собственным бесплатным ключом) позволяет около 5 000 реплик в день. Local AI без лимита и работает на вашем ПК.",
    ["Today’s {limit} Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Лимит {limit} Convai исчерпан.\nMistral (бесплатно, ~5 000/день) или Local AI (без лимита).",
    ["Today’s Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Лимит Convai исчерпан.\nMistral (бесплатно, ~5 000/день) или Local AI (без лимита).",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral, Local AI or Custom as the conversation provider in the settings."] = "Convai сейчас отвечает, поэтому эти изменения пока не действуют. Выберите Mistral, Local AI или Свой в настройках как поставщика бесед.",
    ["Your changes work with Mistral, Local AI and Custom. They do not apply to Convai."] = "Ваши изменения работают с Mistral, Local AI и Своим. На Convai они не действуют.",
    ["Paste"] = "Вставить",
    ["no Omni pack"] = "нет пакета Omni",
    ["Add your Convai API key below to see and buy a plan."] = "Чтобы увидеть планы и купить один из них, добавьте ниже API-ключ Convai.",
    ["Add your Convai API key first."] = "Сначала добавьте API-ключ Convai.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Сначала добавьте API-ключ Convai: скопируйте его, затем выберите «Вставить» в строке «API-ключ Convai».",
    ["Asking Convai for the payment page…"] = "Запрос страницы оплаты у Convai…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Convai проверит, какой план сейчас у вашего ключа. После оплаты это может занять около 15 секунд.",
    ["Billed every month."] = "Списывается каждый месяц.",
    ["Billed once a year."] = "Списывается раз в год.",
    ["Buy"] = "Купить",
    ["Check"] = "Проверить",
    ["Check my plan"] = "Проверить мой план",
    ["Checking your plan…"] = "Проверка плана…",
    ["Choose Check my plan to ask Convai."] = "Выберите «Проверить мой план», чтобы спросить Convai.",
    ["Contacting Convai…"] = "Связь с Convai…",
    ["Convai could not start the payment. Try again later."] = "Convai не удалось начать оплату. Повторите попытку позже.",
    ["Convai did not accept your API key."] = "Convai не приняло ваш API-ключ.",
    ["Convai does not show a paid plan for your key yet."] = "Convai пока не показывает платный план для вашего ключа.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "Convai пока не подтвердило ваш план. Проверьте его в разделе «Настройки > Платный уровень Convai».",
    ["Convai paid tier"] = "Платный уровень Convai",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "Страница оплаты Convai открыта в браузере. Ваш план активируется примерно через 15 секунд после оплаты.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "Служба оплаты Convai не ответила. Попробуйте ещё раз через минуту.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Планы Convai для этого мода: больше бесед Convai на вашем собственном API-ключе Convai. Откроется страница с планами и их ценами.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Беседы с выбранным поставщиком «API-ключ Convai» используют этот план.",
    ["Get your Convai API key"] = "Получить API-ключ Convai",
    ["Manage or cancel plan"] = "Управлять планом или отменить",
    ["Free"] = "Бесплатно",
    ["Gamer, monthly"] = "Gamer, ежемесячно",
    ["Gamer, yearly"] = "Gamer, ежегодно",
    ["Gamer Pro, monthly"] = "Gamer Pro, ежемесячно",
    ["Gamer Pro, yearly"] = "Gamer Pro, ежегодно",
    ["Current plan"] = "Текущий план",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Это ваш текущий план. Чтобы изменить или отменить его, выберите ниже «Управлять планом или отменить».",
    ["No key added"] = "Ключ не добавлен",
    ["Not checked yet"] = "Ещё не проверялось",
    ["Opened in your browser."] = "Открыто в браузере.",
    ["Opening the page in your browser…"] = "Открываем страницу в браузере…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Открывает страницу оплаты Convai (Stripe) в браузере. Вы платите Convai напрямую; мод никогда не видит вашу карту. Ваш план активируется примерно через 15 секунд после оплаты, и беседы затем используют ваш API-ключ Convai.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Открывает convai.com в браузере. Войдите или создайте бесплатный аккаунт, скопируйте свой API-ключ, затем вернитесь и выберите «Вставить» ниже.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Открывает страницу оплаты Convai в браузере. Войдите в тот же аккаунт Convai, чтобы изменить или отменить план.",
    ["Plans"] = "Планы",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Планы, которые Convai создало для этого мода. Они дают вашему собственному API-ключу Convai больше бесед; бесплатный уровень остаётся прежним.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Цены указаны в долларах США. Отменить подписку можно в любой момент на странице оплаты Convai.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "Служба бесед не запущена, поэтому планы показать нельзя. Перезапустите игру.",
    ["This key has no paid plan. Choose a plan below."] = "У этого ключа нет платного плана. Выберите план ниже.",
    ["Your Convai plan"] = "Ваш план Convai",
    ["Your Convai plan is active."] = "Ваш план Convai активен.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Ваш план Convai активен. Выберите «API-ключ Convai» в разделе «Настройки > Поставщик бесед».",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Ваш план Convai активен. Беседы теперь используют ваш API-ключ Convai.",
    ["Your browser could not be opened."] = "Не удалось открыть браузер.",
    ["Your plan could not be read right now. Try again in a moment."] = "Сейчас не удалось прочитать план. Попробуйте ещё раз через минуту.",
    ["{count} Convai interactions a month."] = "{count} взаимодействий Convai в месяц.",
    ["{plan}, {price} a month"] = "{plan}, {price} в месяц",
    ["{plan}, {price} a year"] = "{plan}, {price} в год",
    ["Sign in with Convai"] = "Войти через Convai",
    ["Sign in"] = "Войти",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Открывает страницу входа Convai в браузере.\n\nВойдите или создайте бесплатный аккаунт: ваш API-ключ Convai сохранится на этом компьютере так же, как при «Вставить». У вас есть пять минут.",
    ["Opening Convai’s sign-in page in your browser…"] = "Открываем страницу входа Convai в браузере…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Войдите на странице Convai в браузере. Когда вы закончите, ключ сохранится здесь.",
    ["Signed in. Your Convai API key is saved."] = "Вход выполнен. Ваш API-ключ Convai сохранён.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "Вход занял слишком много времени. Выберите «Войти через Convai», чтобы попробовать снова.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "Вход не был завершён. Попробуйте снова или скопируйте ключ на convai.com и выберите «Вставить».",
    ["Choose one of the listed voices for V."] = "Выберите один из доступных голосов для V.",
    ["Pocket · On your PC"] = "Pocket · На вашем ПК",
    ["Johnny in your head"] = "Джонни в вашей голове",
    ["Johnny in your head is off. Turn it on in Settings > Conversations."] = "Джонни в вашей голове отключён. Включите его в Настройки > Беседы.",
    ["Choose how often Johnny speaks up."] = "Выберите, как часто Джонни подаёт голос.",
    ["A clip you add replaces the shipped voice of this character for Pocket, OmniVoice and the Voxtral cloud voice."] = "Добавленный клип заменяет исходный голос этого персонажа для Pocket, OmniVoice и облачного голоса Voxtral.",
    ["A display name is too long. Keep each one under {max} characters."] = "Отображаемое имя слишком длинное. Каждое должно быть короче {max} символов.",
    ["A new or removed clip counts from the next line this character speaks, once the current reply is over. Nothing needs restarting."] = "Новый или удалённый клип действует со следующей реплики этого персонажа, когда закончится текущий ответ. Ничего перезапускать не нужно.",
    ["A record name can only use letters, digits, dots, dashes and underscores, for example Character.Rebecca."] = "Имя записи может содержать только буквы, цифры, точки, дефисы и подчёркивания, например Character.Rebecca.",
    ["Add a display name"] = "Добавить отображаемое имя",
    ["Add a record name"] = "Добавить имя записи",
    ["Add a record name or a display name, so the game can find this character."] = "Добавьте имя записи или отображаемое имя, чтобы игра могла найти этого персонажа.",
    ["Add voice clip"] = "Добавить голосовой клип",
    ["Another character of yours, {other}, already answers to this record or name."] = "Другой ваш персонаж, {other}, уже откликается на эту запись или имя.",
    ["Choose a gender"] = "Выберите пол",
    ["Choose a gender."] = "Выберите пол.",
    ["Chosen file: {name} ({size}). It is checked when you save it."] = "Выбранный файл: {name} ({size}). Он будет проверен при сохранении.",
    ["Chosen file: {name}, {seconds} seconds."] = "Выбранный файл: {name}, {seconds} сек.",
    ["Clip removed."] = "Клип удалён.",
    ["Delete character"] = "Удалить персонажа",
    ["Delete {name}? The character, its voice clip and what it remembers of you are removed."] = "Удалить {name}? Персонаж, его голосовой клип и всё, что он помнит о вас, будут удалены.",
    ["Display names"] = "Отображаемые имена",
    ["Female"] = "Женский",
    ["Filled in from the character you were facing: {name}."] = "Заполнено по персонажу, которого вы видели перед собой: {name}.",
    ["For example: Character.Rebecca"] = "Например: Character.Rebecca",
    ["For example: Rebecca"] = "Например: Rebecca",
    ["Gender"] = "Пол",
    ["Give the character a name."] = "Дайте персонажу имя.",
    ["How the game finds this character"] = "Как игра находит этого персонажа",
    ["It picks the voice when the character has no clip."] = "Если у персонажа нет клипа, голос выбирается по полу.",
    ["Male"] = "Мужской",
    ["Memories"] = "Воспоминания",
    ["Name"] = "Имя",
    ["New character"] = "Новый персонаж",
    ["No clip yet."] = "Клипа пока нет.",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "Необязательно. Pocket, OmniVoice и облачный голос Voxtral копируют добавленный клип. Без клипа персонаж говорит обычным голосом, соответствующим полу.",
    ["Play saved clip"] = "Воспроизвести сохранённый клип",
    ["Record names"] = "Имена записей",
    ["Remove clip"] = "Удалить клип",
    ["Remove the voice clip? The character goes back to a generic voice."] = "Удалить голосовой клип? Персонаж вернётся к обычному голосу.",
    ["Remove the voice clip? {name} goes back to the shipped voice."] = "Удалить голосовой клип? {name} вернётся к исходному голосу.",
    ["Save clip"] = "Сохранить клип",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "Сначала сохраните персонажа. После этого у него может появиться голосовой клип, и он начнёт запоминать ваши разговоры.",
    ["Saved clip: {seconds} seconds."] = "Сохранённый клип: {seconds} сек.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "Сохранено. Клип немного длинный: лучше всего копируются клипы от 10 до 18 секунд.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "Сохранено. Клип немного короткий: лучше всего копируются клипы от 10 до 18 секунд.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "Этот файл не является записью, которую могут прочитать голоса. Используйте файл WAV, MP3, OGG или FLAC.",
    ["That file is too big for a voice clip."] = "Этот файл слишком большой для голосового клипа.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "Клип почти полностью состоит из тишины. Используйте клип, в котором кто-то говорит большую часть времени.",
    ["The clip is too long. Use at most {max} seconds."] = "Клип слишком длинный. Используйте не более {max} секунд.",
    ["The clip is too short. Use at least {min} seconds."] = "Клип слишком короткий. Используйте не менее {min} секунд.",
    ["The game did not name anyone. Face the character, then choose Settings > Edit characters > Open in the game again."] = "Игра никого не назвала. Повернитесь к персонажу и затем снова выберите в игре Настройки > Редактировать персонажей > Открыть.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "Игра узнаёт собеседника по имени записи, отображаемому имени или по обоим. Имя записи выглядит, например, так: Character.Rebecca или NCA.Rebecca. Добавьте хотя бы одно.",
    ["The name is too long. Keep it under {max} characters."] = "Имя слишком длинное. Оно должно быть короче {max} символов.",
    ["The name of the character’s record in the game files."] = "Имя записи персонажа в файлах игры.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "Имя, под которым известен персонаж. Он называет его, когда кто-то спрашивает, кто он.",
    ["The name the game shows for the character."] = "Имя, которое игра показывает для персонажа.",
    ["The recording is distorted. Record it again, a little quieter."] = "Запись искажена. Запишите её заново, немного тише.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "Качество записи слишком низкое. Используйте не менее {min} Hz.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "Запись слишком тихая, чтобы её скопировать. Запишите громче или ближе к микрофону.",
    ["The saved clip could not be loaded."] = "Не удалось загрузить сохранённый клип.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "Слова в клипе слишком длинные. Сделайте их короче {max} символов.",
    ["This character speaks with a generic voice that fits the gender."] = "Этот персонаж говорит обычным голосом, соответствующим полу.",
    ["This character speaks with the shipped voice."] = "Этот персонаж говорит исходным голосом.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "Этот компьютер не может преобразовать такой файл. Сохраните его как WAV и попробуйте снова.",
    ["Too many display names. Keep {max} or fewer."] = "Слишком много отображаемых имён. Оставьте не больше {max}.",
    ["Too many record names. Keep {max} or fewer."] = "Слишком много имён записей. Оставьте не больше {max}.",
    ["Type the words said in the clip, at least {min} characters."] = "Введите слова, сказанные в клипе, не менее {min} символов.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "Введите то, что говорится в клипе, так, как это произносится. OmniVoice нужно это, чтобы скопировать голос.",
    ["Use the character I’m facing"] = "Использовать персонажа, на которого я смотрю",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "Используйте запись, на которой один человек говорит чётко, без музыки и других голосов, длиной от {min} до {max} секунд. Лучше всего копируются клипы от {goodMin} до {goodMax} секунд. WAV, MP3, OGG или FLAC.",
    ["Voice"] = "Голос",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "Кто этот персонаж, что он знает и как выглядит. Лучше всего писать в форме «Я …». Длинная биография замедляет ответы, поэтому делайте её короткой.",
    ["Words said in the clip"] = "Слова, сказанные в клипе",
    ["You have as many voice clips as the editor keeps ({max}). Remove one first."] = "У вас уже столько голосовых клипов, сколько хранит редактор ({max}). Сначала удалите один.",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "Вы уже создали столько персонажей, сколько может хранить редактор ({max}). Сначала удалите один.",
    ["Your character"] = "Ваш персонаж",
    ["Your characters"] = "Ваши персонажи",
    ["Your own characters talk only with Mistral, Local AI or Custom. With Convai they speak as an ordinary person."] = "Ваши собственные персонажи говорят только с Mistral, Local AI или Своим. С Convai они говорят как обычные люди.",
    ["{name} is one of your own characters. They need Mistral, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} — один из ваших собственных персонажей. Ему нужен Mistral, Local AI или Свой, поэтому с Convai он говорит как обычный человек.",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "У {other} уже есть профиль в моде, и этот профиль всегда важнее. Используйте другую запись или имя.",
    ["A pack is one folder too deep. See Help in Settings."] = "Пакет на одну папку глубже. См. Справку в Настройках.",
    ["All files found."] = "Все файлы найдены.",
    ["Browser"] = "Браузер",
    ["Found."] = "Найдено.",
    ["Found: {list}."] = "Найдено: {list}.",
    ["Game version"] = "Версия игры",
    ["Graphics card"] = "Видеокарта",
    ["Internet"] = "Интернет",
    ["Loaded."] = "Загружено.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "Local AI не удалось запустить. Сформируйте отчёт ниже и отправьте его или выберите другого поставщика бесед.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "Local AI не нашёл подходящей видеокарты. Нужна карта NVIDIA или AMD с актуальным драйвером. Обновите драйвер или выберите другого поставщика бесед.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Отсутствуют: {files}. Распакуйте архив Scripts в папку Cyberpunk 2077 заново и разрешите замену файлов.",
    ["Mod files"] = "Файлы мода",
    ["Mod manager"] = "Менеджер модов",
    ["Moved into place from {folder}: {packs}."] = "Перемещено из {folder}: {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Пакет Local AI не найден. Скачайте его со страницы мода на Hugging Face и распакуйте в папку Cyberpunk 2077 или выберите другого поставщика бесед.",
    ["No problem found. Select a line to see what was checked."] = "Проблем не найдено. Выберите строку, чтобы увидеть, что проверялось.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the Runtime zip straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The Runtime is a separate download from the mod’s Hugging Face page; the Nexus page links to it."] = "В этом сеансе службы бесед не видно: Runtime отсутствует или не загрузился. Распакуйте архив Runtime прямо в папку Cyberpunk 2077 (не в новую папку), проверьте, что там есть red4ext/plugins/AiNpcCyberpunkMod, и перезапустите игру. Runtime скачивается отдельно со страницы мода на Hugging Face; ссылка есть на странице Nexus.",
    ["None found: installed by hand."] = "Не найдено: установлено вручную.",
    ["None installed. They are optional."] = "Ничего не установлено. Они необязательны.",
    ["Not needed: Local AI and the voice run on this PC."] = "Не нужно: Local AI и голос работают на этом ПК.",
    ["Not used"] = "Не используется",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Не ваш поставщик бесед. Выберите его в меню Настройки > Поставщик бесед.",
    ["Note"] = "Примечание",
    ["OK"] = "OK",
    ["Optional packs"] = "Дополнительные пакеты",
    ["Problem"] = "Проблема",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Найдено проблем: {count}. Выберите строку с пометкой «Проблема», чтобы прочитать, что делать.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "RED4ext не загружен. Установите его с Nexus Mods и перезапустите игру. Он также запускает службу бесед.",
    ["Reached {host}."] = "Связь с {host} установлена.",
    ["Scripts and Runtime"] = "Scripts и Runtime",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} и Runtime {runtime}.",
    ["Setup check"] = "Проверка установки",
    ["Some mod files are missing. Extract the Scripts zip again. See Help in Settings."] = "Не хватает файлов мода. Распакуйте архив Scripts заново. См. Справку в Настройках.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Некоторые файлы пакета не удалось переместить, потому что на их месте уже лежат другие файлы. Распакуйте пакет в папку Cyberpunk 2077 заново и разрешите замену файлов.",
    ["The Runtime is incomplete ({code}). Download it again and extract it into the Cyberpunk 2077 folder (or apply the Runtime update zips in order), then restart the game."] = "Runtime неполный ({code}). Скачайте его заново, распакуйте в папку Cyberpunk 2077 (или примените zip-обновления Runtime по порядку) и перезапустите игру.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the Runtime zip straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "Файл настроек запуска launcher.ini отсутствует в red4ext/plugins/AiNpcCyberpunkMod, поэтому игра не может запустить службу разговоров. Распакуйте zip с Runtime заново прямо в папку Cyberpunk 2077 (вручную, даже если используете Vortex), заменив файлы, и перезапустите игру.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "Служба бесед не может подключиться к интернету. См. Справку в Настройках.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "Служба бесед не может подключиться к {host}. Разрешите Node.js в брандмауэре или антивирусе (Windows спросит один раз; выберите «Разрешить доступ»), проверьте подключение к интернету и перезапустите игру.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "Служба бесед не смогла запуститься ({code}). Перезапустите игру. Если это повторится, сформируйте отчёт ниже и отправьте его.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "Служба бесед не запустилась. Установлен ли Runtime? См. Справку в Настройках.",
    ["The game version could not be read."] = "Не удалось определить версию игры.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Этот ПК не может найти {host}. Проверьте подключение к интернету и перезапустите игру.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Откройте r6/logs/redscript_rCURRENT.log. Указанный там мод блокирует скрипты.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware or redscript, or a game version other than {game}, can also cause it."] = "Скрипты этого мода не загрузились. Откройте r6/logs/redscript_rCURRENT.log. Если в ошибке назван другой мод, проблема в нём. Причиной могут быть и отсутствующий или устаревший Codeware или redscript, либо версия игры, отличная от {game}.",
    ["Missing: {names}. Install them and restart the game."] = "Отсутствуют: {names}. Установите их и перезапустите игру.",
    ["Install or update: {names}. Then restart the game."] = "Установите или обновите: {names}. Затем перезапустите игру.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "Codeware слишком старый. Обновите его с Nexus Mods и перезапустите игру.",
    ["Version {version}."] = "Версия {version}.",
    ["Version {version}. The mod is tested on {game} only, so some things may not work."] = "Версия {version}. Мод проверен только на версии {game}, поэтому некоторые вещи могут не работать.",
    ["Version {version}. These files are the mod build for game {build}. Install the build made for game {game} from the mod’s Nexus Mods page (Scripts) and Hugging Face page (Runtime), then restart the game."] = "Версия {version}. Эти файлы — сборка мода для игры {build}. Установите сборку для игры {game} со страницы мода на Nexus Mods (Scripts) и со страницы Hugging Face (Runtime), затем перезапустите игру.",
    ["Vortex. Install the Runtime and the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say."] = "Vortex. Установите Runtime и дополнительные пакеты вручную в папку Cyberpunk 2077, как сказано в шагах установки.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "{name} отсутствует. Установите его с Nexus Mods и перезапустите игру.",
    ["{name}, {memory} GB of video memory."] = "{name}, видеопамять: {memory} ГБ.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} лежит на одну папку глубже, чем нужно, в {folder}. Перезапустите игру, и мод сам переместит файлы на место. Если они останутся там, переместите находящуюся внутри папку red4ext в папку Cyberpunk 2077.",
    ["Add an endpoint URL and a model ID first."] = "Сначала добавьте URL эндпоинта и ID модели.",
    ["Convai: the custom provider is not set up yet"] = "Convai: свой поставщик ещё не настроен",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Скопируйте базовый URL у поставщика, например https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 или http://localhost:11434/v1 (Ollama). Он один раз считывается из буфера обмена и сохраняется на этом компьютере.\n\nhttp:// можно использовать только на этом компьютере и в домашней сети. Также можно указать endpoint=, model= и api-key= в файле player-custom-endpoint.txt в папке службы бесед.\n\nНичего не отправляется, пока вы не выберете этого поставщика или не нажмёте «Проверить связь».",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Сначала скопируйте ID модели у поставщика, например meta-llama/llama-3.1-8b-instruct (OpenRouter) или llama3.2 (Ollama). Он один раз считывается из буфера обмена и сохраняется на этом компьютере.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Сначала скопируйте API-ключ у поставщика. Он один раз считывается из буфера обмена и сохраняется только на этом компьютере. Локальному серверу, например Ollama или LM Studio, ключ обычно не нужен.",
    ["Custom (OpenAI-compatible)"] = "Свой (OpenAI-compatible)",
    ["Custom API key"] = "Свой API-ключ",
    ["Custom endpoint URL"] = "Свой URL эндпоинта",
    ["Custom model ID"] = "Свой ID модели",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Ответы своего поставщика читает местный голос, не облачный голос Convai.",
    ["Custom: key not accepted"] = "Свой: ключ не принят",
    ["Custom: model unavailable"] = "Свой: модель недоступна",
    ["Custom: out of credits"] = "Свой: кончились кредиты",
    ["Custom: rate limited for now"] = "Свой: временно ограничено",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Удаляет сохранённый URL эндпоинта. Свому поставщику он нужен для ответов.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Удаляет сохранённый ключ. Потом ответы своего поставщика запрашиваются без ключа.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Удаляет сохранённый ID модели. Свому поставщику он нужен для ответов.",
    ["Failed"] = "Ошибка",
    ["It answered in {ms} ms."] = "Ответ за {ms} мс.",
    ["It could not be saved."] = "Не удалось сохранить.",
    ["Model ID: {model}"] = "ID модели: {model}",
    ["Only https:// works outside this computer and your home network."] = "Вне этого компьютера и домашней сети работает только https://.",
    ["Paste API key"] = "Вставить API-ключ",
    ["Paste endpoint URL"] = "Вставить URL",
    ["Paste model ID"] = "Вставить ID модели",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Отправляет эндпоинту одно короткое сообщение с сохранённым ID модели и ключом и показывает ответ. Почти не тратит кредиты.",
    ["Test"] = "Тест",
    ["Test connection"] = "Проверить связь",
    ["Testing the connection…"] = "Проверка связи…",
    ["Testing…"] = "Проверка…",
    ["That is too long."] = "Это слишком длинно.",
    ["That was not accepted."] = "Не принято.",
    ["The account is out of credits. Add credits with your provider."] = "На счёте закончились кредиты. Пополните их у поставщика.",
    ["The address must start with https:// or http://."] = "Адрес должен начинаться с https:// или http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "Адрес ведёт в другое место. Используйте конечный адрес от поставщика.",
    ["That address is a web page, not the API. For OpenRouter use https://openrouter.ai/api/v1."] = "Этот адрес — веб-страница, а не API. Для OpenRouter используйте https://openrouter.ai/api/v1.",
    ["That address is a web page, not the API. Use the API address from your provider."] = "Этот адрес — веб-страница, а не API. Используйте адрес API от вашего поставщика.",
    ["A model ID is a short name like that, not a web address."] = "ID модели — это короткое название вроде этих, а не веб-адрес.",
    ["The clipboard does not hold a model ID."] = "В буфере обмена нет ID модели.",
    ["The clipboard does not hold a web address."] = "В буфере обмена нет веб-адреса.",
    ["The clipboard does not hold an API key."] = "В буфере обмена нет API-ключа.",
    ["The clipboard is empty. Copy it first."] = "Буфер обмена пуст. Сначала скопируйте.",
    ["The connection test failed."] = "Проверка связи не удалась.",
    ["The connection works. The endpoint accepted your model and key."] = "Связь работает. Эндпоинт принял вашу модель и ключ.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "Служба бесед не запущена, поэтому проверить ничего нельзя. Перезапустите игру.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Свой поставщик не принял ключ. Проверьте его в меню Настройки > Поставщик бесед.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Свой поставщик не ответил. Проверьте адрес в Настройках или попробуйте снова.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Свой поставщик не знает этот ID модели. Проверьте в Настройках.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Свой поставщик не задан, работает Convai. Добавьте URL и ID модели в Настройках.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "Свой поставщик ограничивает запросы. Попробуйте через минутку.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Свой поставщик сообщает: на счёте нет кредитов. Пополните и попробуйте снова.",
    ["The endpoint URL was removed."] = "URL эндпоинта удалён.",
    ["The endpoint answered with no text. Check the model ID."] = "Эндпоинт ответил без текста. Проверьте ID модели.",
    ["The endpoint did not accept your API key."] = "Эндпоинт не принял ваш API-ключ.",
    ["The endpoint did not answer. Check its address."] = "Эндпоинт не ответил. Проверьте адрес.",
    ["The endpoint does not know that model ID."] = "Эндпоинт не знает этот ID модели.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "Эндпоинт ограничивает запросы. Попробуйте через минутку.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "Эндпоинт ограничивает запросы. Подождите около {seconds} сек. и попробуйте снова.",
    ["The endpoint refused the request. Check the model ID and the address."] = "Эндпоинт отклонил запрос. Проверьте ID модели и адрес.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "Эндпоинт сообщил об ошибке на своей стороне. Попробуйте через минутку.",
    ["The endpoint took too long to answer."] = "Эндпоинт слишком долго отвечал.",
    ["The model ID was removed."] = "ID модели удалён.",
    ["The provider said: {detail}"] = "Поставщик ответил: {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Адрес не зашифрован, но на вашем компьютере или в домашней сети это нормально.",
    ["Use the base URL only: no password, query or #."] = "Укажите только базовый URL: без пароля, параметров запроса и #.",
    ["Waiting for the endpoint to answer…"] = "Ожидание ответа эндпоинта…",
    ["Custom: free daily limit reached"] = "Свой: дневной бесплатный лимит исчерпан",
    ["New address saved. Paste your API key again for it."] = "Новый адрес сохранён. Вставьте для него API-ключ ещё раз.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Дневной бесплатный лимит этой модели исчерпан. Сбросится в {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Дневной бесплатный лимит этой модели исчерпан. Попробуйте снова после сброса.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Модель тратит ответ на раздумья. Выберите в Настройках модель без рассуждений.",
    ["All"] = "Все",
    ["Also changed: {names}."] = "Также изменено: {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Выберите любого персонажа из списка ниже. Его присутствие в группе не требуется.",
    ["Defaults restored."] = "Значения по умолчанию восстановлены.",
    ["Drag the slider, or press left and right, to turn the page."] = "Перетащите ползунок или нажмите влево и вправо, чтобы переключить страницу.",
    ["How loud the mod’s voices are, for companions, characters and V’s typed lines. 100 is the normal level.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. The game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Насколько громко звучат голоса мода: напарников, персонажей и реплик, которые вы набираете за V. 100 — обычный уровень.\n\nВыше 100 голоса звучат громче, лимитер не даёт им хрипеть. Диалоги и звуки самой игры не меняются.\n\nСледующий ответ использует значение.",
    ["Not available right now."] = "Сейчас недоступно.",
    ["Open Settings to restore its defaults."] = "Откройте настройки, чтобы восстановить значения по умолчанию.",
    ["Page"] = "Страница",
    ["Show only the models whose name starts with this letter."] = "Показывать только модели, название которых начинается с этой буквы.",
    ["Starts with"] = "Начинается с",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Откройте AI NPC Cyberpunk Mod в списке Mods.",
    ["The settings could not be saved. Nothing was changed."] = "Не удалось сохранить настройки. Ничего не было изменено.",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Mistral (with your free key, about 5,000 turns a day) or Local AI (unlimited)."] = "Вы уже использовали сегодняшние {limit} реплик. Они вернутся завтра. Чтобы продолжить прямо сейчас, выберите Mistral (с бесплатным ключом, примерно 5 000 реплик в день) или Local AI (без лимита).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Кто пишет ответы ваших напарников. Изменение ждёт, пока ни одна беседа не выполняется.\n\nБесплатный тариф Convai не требует настройки и даёт лучшие ответы. Вариант «API-ключ Convai» использует ваш ключ, а Mistral работает на бесплатном тарифе с вашим бесплатным ключом; память остаётся на этом компьютере.\n\nС Mistral, Local AI или Своим облачный голос Convai заменяется локальным голосом. Речь распознаётся на этом компьютере, поэтому клавиша голоса работает.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Кто пишет ответы ваших напарников. Изменение ждёт, пока ни одна беседа не выполняется.\n\nБесплатный тариф Convai не требует настройки и даёт лучшие ответы. Вариант «API-ключ Convai» использует ваш ключ, а Mistral работает на бесплатном тарифе с вашим бесплатным ключом; память остаётся на этом компьютере.\n\nС Mistral, Local AI или Своим облачный голос Convai заменяется локальным голосом. Распознавание речи для клавиши голоса с ними пока недоступно, поэтому вводите сообщения текстом.",
    ["Privacy"] = "Конфиденциальность",
    ["Send error reports automatically"] = "Автоотправка отчётов об ошибках",
    ["Error reports go to the developer automatically. Turn them off in Settings > Privacy."] = "Отчёты об ошибках сами уходят разработчику. Выкл.: Настройки > Конфиденциальность.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "Для «Управления напарниками» нужен Mod Configuration Menu 0.10.5+ или Native Settings UI",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "Обновите Mod Configuration Menu до 0.10.5+ или установите Native Settings UI",
    ["Stand up to open the Companion Manager"] = "Встаньте, чтобы открыть «Управление напарниками»",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI {nsui} or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "Для «Управления напарниками» нужен Mod Configuration Menu 0.10.5 или новее, либо Native Settings UI {nsui} или новее. Достаточно любого из них. Установите один из них с Nexus Mods и перезапустите игру.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer, or install Native Settings UI, then restart the game."] = "Mod Configuration Menu слишком старый. Обновите его до 0.10.5 или новее, или установите Native Settings UI, и перезапустите игру.",
    ["Previous page"] = "Предыдущая страница",
    ["Next page"] = "Следующая страница",
    ["Starts with: {letter}"] = "Начинается с: {letter}",
    ["Characters and party"] = "Персонажи и группа",
    ["Load a save first"] = "Загрузите сохранение",
    ["Inviting characters and managing your party need a loaded game."] = "Приглашать персонажей и управлять группой можно только в загруженной игре.",
    ["Voxtral (recommended)"] = "Voxtral (рекомендуем)",
    ["Defaults"] = "Стандарт",
    ["Press Confirm to put every setting back to its default."] = "Нажмите «Подтвердить», чтобы вернуть каждую настройку к значению по умолчанию.",
    ["Local AI stopped working and was restarted."] = "Local AI перестал работать и был перезапущен.",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "Local AI здесь работает в основном на процессоре, поэтому ответы медленные.",
    ["The yellow border is Windows showing a capture. Choose Mistral or Local AI to stop it."] = "Жёлтая рамка: Windows показывает снимок. Выберите Mistral или Local AI, чтобы её убрать.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate. The microphone uses this language as a hint for non-English speech."] = "Меняет только меню и уведомления этого мода.\n\nГолоса персонажей и язык, на котором вы говорите, — отдельные настройки. Микрофон использует этот язык как подсказку для речи не на английском.",
    ["Voxtral stops speaking; companion replies show as text until a key is saved."] = "Voxtral перестаёт говорить; ответы напарников показываются текстом, пока не будет сохранён ключ.",
    ["Conversations go back to Convai free tier."] = "Беседы снова пойдут через Convai (бесплатный тариф).",
    ["Deletes the saved key."] = "Удаляет сохранённый ключ.",
    ["Nothing you use now depends on it."] = "Ничего из того, что вы используете сейчас, от этого не зависит.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "Облачный голос Convai не может использовать «Естественную речь», поэтому она выключена.",
    ["Custom endpoint"] = "Свой эндпоинт",
    ["Speaks up often"] = "Часто подаёт голос",
    ["Speaks up rarely"] = "Редко подаёт голос",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "Адрес, API-ключ и ID модели вашего поставщика OpenAI-compatible, а также проверка связи. Используется, когда поставщиком бесед выбран «Свой».",
    ["V’s voice switches from Voxtral to Pocket."] = "Голос V переключается с Voxtral на Pocket.",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · нужен пакет Omni",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · нужен голос Omni",
    ["Requires the Companion voices to be an OmniVoice choice"] = "Требует, чтобы голоса напарников были OmniVoice",
    ["V’s voice switches from OmniVoice to Pocket."] = "Голос V переключается с OmniVoice на Pocket.",
    ["V’s voice"] = "Голос V",
    ["V (male voice)"] = "V (мужской голос)",
    ["V (female voice)"] = "V (женский голос)",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "Используется для набранных реплик V: Pocket, OmniVoice и облачный голос Voxtral копируют его.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "V говорит голосом установленного мода на голос V или исходным голосом V.",
    ["Remove the voice clip? V goes back to the voice of your installed V voice mod, or the shipped V voice."] = "Удалить голосовой клип? V вернётся к голосу установленного мода на голос V или к исходному голосу.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "OmniVoice нужна видеокарта NVIDIA, а в этом ПК нет рабочей. Ответы показываются текстом. Чтобы слышать голоса, выберите Pocket в Настройках.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "OmniVoice нужна видеокарта NVIDIA, а в этом ПК нет рабочей. Напарники вместо этого используют {voice}.",
    ["OmniVoice needs NVIDIA"] = "OmniVoice требует NVIDIA",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "В этом ПК нет видеокарты NVIDIA, которая нужна OmniVoice. OmniVoice здесь не запустится. Выберите Pocket, чтобы слышать голоса.",
    ["{voice} · needs NVIDIA card"] = "{voice} · нужна карта NVIDIA",
    ["{language} replies show as text: the {language} multilingual pack is missing."] = "Ответы «{language}» текстом: нет многоязычного пакета «{language}».",
    ["French"] = "французский",
    ["Italian"] = "итальянский",
    ["German"] = "немецкий",
    ["Spanish"] = "испанский",
    ["Portuguese"] = "португальский",

    ["OmniVoice needs more graphics memory than is free next to the game. Pocket is used."] = "OmniVoice нужно больше видеопамяти, чем свободно рядом с игрой. Используется Pocket.",
    ["Windows ran out of memory for the voice. A larger paging file or closing other apps helps."] = "У Windows нет памяти для голоса. Увеличьте файл подкачки или закройте программы.",
    ["OmniVoice needs 12 GB"] = "OmniVoice требует 12 ГБ",
    ["{voice} · needs 12 GB card"] = "{voice} · нужна карта на 12 ГБ",
    ["The graphics card in this PC has less than the 12 GB OmniVoice needs next to the game. If it cannot start, Pocket is used. Choose Pocket to skip the wait."] = "У видеокарты этого ПК меньше 12 ГБ, которые нужны OmniVoice рядом с игрой. Если он не может запуститься, используется Pocket. Чтобы не ждать, выберите Pocket.",
    ["Forget all memories ({count} characters)"] = "Удалить все воспоминания ({count} персонажей)",
    ["Dynamic info"] = "Живая информация",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Mistral, Local AI and Custom)."] = "То, что игра сообщает каждому персонажу о текущем моменте. Персонаж упоминает это, только когда это подходит к разговору.\n\nОтключённая группа не передаётся ни одному поставщику бесед (Convai, Mistral, Local AI и Свой).",
    ["Location"] = "Место",
    ["Where V is: the district, and V’s apartment or the named place when the game says so.\n\nOff: characters are not told where you are, and the mod stops reading it from the game. The picture Convai gets of what V sees, and an add-on’s own text, are not affected."] = "Где находится V: район, квартира V или названное место, если игра его указывает.\n\nВыключено: персонажи не узнают, где вы, а мод перестаёт считывать это из игры. Образ, который Convai получает о том, что видит V, и текст самого дополнения не меняются.",
    ["Time and weather"] = "Время и погода",
    ["The hour of the day and the weather in Night City.\n\nOff: nobody is told the time or the weather, and the mod stops reading them from the game."] = "Время суток и погода в Найт-Сити.\n\nВыключено: никто не узнаёт время и погоду, а мод перестаёт считывать их из игры.",
    ["Company and vehicle"] = "Компания и транспорт",
    ["Who else is with V, whether V is on foot or in a vehicle, and what a companion is doing beside V.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Кто ещё рядом с V, идёт ли V пешком или едет в транспорте и что делает напарник рядом с V.\n\nВыключено: ничего из этого не передаётся, а мод перестаёт считывать это из игры.",
    ["Health, heat and fights"] = "Здоровье, розыск и бои",
    ["V’s health, the police heat on V, and the last fight V was in.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Здоровье V, уровень розыска полиции в отношении V и последний бой V.\n\nВыключено: ничего из этого не передаётся, а мод перестаёт считывать это из игры.",
    ["V’s money"] = "Деньги V",
    ["A rough idea of how many eddies V has: nearly broke, short, comfortable or rich.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Примерно сколько эдди у V: почти без денег, мало, достаточно или богато.\n\nВыключено: это не передаётся, а мод перестаёт считывать это из игры.",
    ["V’s gear and clothes"] = "Снаряжение и одежда V",
    ["What V wears and carries: clothes, weapons and cyberware that can be seen.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Что V носит и несёт с собой: одежду, оружие и видимые кибернетические импланты.\n\nВыключено: это не передаётся, а мод перестаёт считывать это из игры.",
    ["V’s gender and lifepath"] = "Пол и жизненный путь V",
    ["Whether V is a woman or a man, and V’s lifepath: Nomad, Street Kid or Corpo.\n\nOff: it is not sent with a turn, and the mod stops reading it for that. Your story’s own facts may still reflect your lifepath."] = "Пол V (женщина или мужчина) и жизненный путь V: Кочевник, Дитя улиц или Корпорат.\n\nВыключено: это не передаётся с каждой репликой, и мод перестаёт считывать это из игры для этого. Факты самой истории по-прежнему могут отражать жизненный путь V.",
    ["Quest and journal"] = "Задание и журнал",
    ["V’s tracked quest and its objectives, the jobs V has open and the journal history.\n\nWhat each character knows about your story stays on.\n\nOff: none of this is sent. The mod stops scanning the journal for it, unless Johnny’s remarks are on."] = "Отслеживаемое задание V и его цели, открытые заказы V и история журнала.\n\nТо, что каждый персонаж знает о вашей истории, остаётся включённым.\n\nВыключено: ничего из этого не передаётся. Мод перестаёт сканировать журнал, если реплики Джонни не включены.",
    ["Recent game dialogue"] = "Недавние реплики из игры",
    ["The last lines spoken in scenes and V’s chosen replies, so a character can pick up from what was just said.\n\nOff: they are not sent."] = "Последние реплики в сценах и выбранные V ответы, чтобы персонаж мог продолжить с того, что только что прозвучало.\n\nВыключено: они не передаются.",
    ["The Runtime is out of date. Apply its update zips one by one, or get the full Runtime."] = "Runtime устарел. Примените его zip-обновления по порядку или скачайте полный Runtime.",
    ["The Scripts and Runtime do not match. Update whichever is older. See Help in Settings."] = "Scripts и Runtime не совпадают. Обновите более старый. См. Справку в Настройках.",
    ["Scripts {scripts} and Runtime {runtime} do not match: the Runtime is out of date. Apply the Runtime update zips from the updates folder on the mod’s Hugging Face page one by one, starting from your version, or download the full Runtime. Extract each into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} и Runtime {runtime} не совпадают: Runtime устарел. Примените по порядку zip-обновления Runtime из папки updates на странице мода на Hugging Face, начиная с вашей версии, или скачайте полный Runtime. Распакуйте каждый в папку Cyberpunk 2077 и перезапустите игру.",
    ["Scripts {scripts} and Runtime {runtime} do not match. Update whichever is older: the Scripts from Nexus Mods, or the Runtime from the mod’s Hugging Face page (its update zips one by one, or the full Runtime). Extract into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} и Runtime {runtime} не совпадают. Обновите более старый: Scripts с Nexus Mods или Runtime со страницы мода на Hugging Face (его zip-обновления по порядку или полный Runtime). Распакуйте в папку Cyberpunk 2077 и перезапустите игру.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Download the full Runtime from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, then restart the game."] = "Служба бесед не ответила на проверку установки, поэтому её Runtime, вероятно, старше этих Scripts. Скачайте полный Runtime со страницы мода на Hugging Face, распакуйте в папку Cyberpunk 2077 и перезапустите игру.",
    ["The Runtime update from {from} to {to} was never applied, so some Runtime files are old. Apply the Runtime update zips from the updates folder on the mod’s Hugging Face page one by one, starting from your version. Extract each into the Cyberpunk 2077 folder, then restart the game."] = "Обновление Runtime с {from} до {to} так и не было применено, поэтому некоторые файлы Runtime устарели. Примените по одному zip-обновления Runtime из папки updates на странице мода на Hugging Face, начиная с вашей версии. Распакуйте каждый в папку Cyberpunk 2077 и перезапустите игру.",
    ["A Runtime update step is missing. Apply its update zips one by one from the updates folder."] = "Пропущено обновление Runtime. Примените zip из папки updates по очереди.",
    ["Character unavailable in this game installation."] = "Персонаж недоступен в этой установке игры.",
    ["Message could not be delivered. Please try again."] = "Не удалось доставить сообщение. Попробуйте ещё раз.",
    ["The conversation service could not reply. Please try again."] = "Служба бесед не смогла ответить. Попробуйте ещё раз.",
    ["Voice conversation failed. Check your microphone and try again."] = "Голосовой разговор не удался. Проверьте микрофон и попробуйте снова.",
    ["{name} is one of your own characters. They need Mistral, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name} — один из ваших собственных персонажей. Этому персонажу нужен Mistral, Local AI или Custom: выберите один из них в настройках, в пункте «Поставщик бесед».",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. It stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Напарники время от времени делают паузу, запинаются, смеются или вздыхают — как того требует их характер. Это случается редко.\n\nOmniVoice умеет озвучивать смех и вздохи; другие голоса лишь добавляют паузы.\n\nНедоступно с облачным голосом Convai: выбор облачного голоса отключает эту функцию, а включение переводит голос на Pocket.",
    ["Copy your free key from Mistral first (signing up there needs phone verification). It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder. Mistral allows about one message a second and about 5,000 turns a day."] = "Сначала скопируйте бесплатный ключ из Mistral (регистрация требует подтверждения телефона). Он один раз считывается из буфера обмена, проверяется в Mistral и сохраняется на этом компьютере.\n\nТакже его можно сохранить в файле player-mistral-key.txt в папке службы бесед. Mistral позволяет около одного сообщения в секунду и около 5 000 реплик в день.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups, writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nFailures, preparation progress and joined notices stay visible when it is off."] = "Для тестов и отчётов об ошибках; в обычной игре оставьте выключенным.\n\nПоказывает служебные всплывающие окна, записывает трассу движения в рабочую папку мода, пишет в журнал решения о жестах и добавляется в отчёты поддержки.\n\nХод подготовки, уведомления о присоединении и ошибки остаются видимыми и при выключенной опции.",
    ["Pocket: the lightest, on your CPU, about 0.2 s to the first word.\n\nOmniVoice: richer, needs a capable GPU and its pack, 1 to 2.5 s.\n\nVoxtral: cloud voices with your Mistral key. The companions’ voice loads no local model; V’s typed lines follow V’s own voice setting.\n\nConvai: its own cloud voice. A voice that cannot run shows replies as text."] = "Pocket: самый лёгкий, работает на процессоре, первое слово примерно через 0,2 с.\n\nOmniVoice: богаче, нужна мощная видеокарта и его пакет, 1–2,5 с.\n\nVoxtral: голоса из облака с вашим ключом Mistral. Голоса напарников не загружают локальную модель; реплики, которые вводит V, следуют настройке голоса V.\n\nConvai: собственный облачный голос. Голос, который не может работать, показывает ответы текстом.",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand, with their own voice and memory.\n\nNothing else about them changes: they do not turn, move, gesture or follow, and stay quiet during scenes, quest conversations, fights and rides.\n\nTakes effect after you reload your save."] = "Именованные персонажи самой игры, например Judy, Jackie, Panam и Rogue, отвечают, когда вы обращаетесь к ним там, где они стоят, своим голосом и с собственной памятью.\n\nБольше ничего в них не меняется: они не поворачиваются, не двигаются, не жестикулируют и не следуют за вами. Во время сцен, сюжетных разговоров, боёв и поездок молчат.\n\nВступает в силу после загрузки сохранения.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Extract Runtime update zips and multilingual packs into the Runtime’s own mod folder, not as new mods. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. Файлы, которые создаёт мод, попадают в его папку Overwrite; оставьте их там. Распакуйте zip-обновления Runtime и многоязычные пакеты в собственную папку мода Runtime, а не как новые моды. Упомяните Mod Organizer 2, когда отправляете отчёт.",
    ["Mod Organizer 2: extract update zips into the Runtime’s own mod folder, not as new mods."] = "Mod Organizer 2: распакуйте zip-обновления в собственную папку Runtime, а не как новые моды.",
    ["When something in the mod goes wrong, a short report goes to the developer so it can be fixed.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name.\n\nIt holds the error, versions, your settings, PC details (graphics card, processor, Windows, security software, game drive, screen), installed mod names, setup check, reply timings and the log lines around it."] = "Когда в моде что-то идёт не так, короткий отчёт отправляется разработчику, чтобы это исправили.\n\nОн никогда не содержит ключей, того, что говорите вы или персонажи, воспоминаний, аудио и имени вашей учётной записи Windows.\n\nВ нём есть ошибка, версии, ваши настройки, данные о ПК (видеокарта, процессор, Windows, защита, диск с игрой, экран), названия модов, проверка установки, время ответов и строки лога об ошибке.",
    ["Some Runtime files are from a newer update than this Runtime says. Apply the Runtime update zips from the updates folder on the mod’s Hugging Face page one by one, in order, starting from your version, or extract the full Runtime again. Then restart the game."] = "Часть файлов Runtime относится к более новому обновлению, чем указано для этого Runtime. Примените zip-файлы обновления Runtime из папки updates на странице мода на Hugging Face по одному, по порядку, начиная с вашей версии, или заново распакуйте полный Runtime. Затем перезапустите игру.",
    ["Multilingual pack ({code})"] = "Многоязычный пакет ({code})",
    ["PocketTTS model ({code})"] = "Модель PocketTTS ({code})",
    ["Your typed lines are spoken out loud too, in the V voice that matches yours, then the companion answers. V’s line is always waited for, up to about 30 s without audio.\n\nPocket: on your processor, about 0.2 s (its own small model if the companions use another voice). Voxtral: cloud, with your Mistral key. OmniVoice: the companions’ GPU voice, a second more wait."] = "Введённые реплики тоже озвучиваются вслух, голосом V, подходящим вашему персонажу, затем отвечает напарник. На реплику V всегда ждём, но не дольше примерно 30 с без звука.\n\nPocket: на процессоре, примерно 0,2 с (со своей небольшой моделью, если напарники используют другой голос). Voxtral: в облаке, с вашим ключом Mistral. OmniVoice: GPU-голос напарников, ещё секунда ожидания.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with Mistral, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Редактируйте в браузере биографии, правила и воспоминания персонажей, а также промпт для каждого варианта ИИ.\n\nРаботает с Mistral, Local AI и Своим, но не с Convai. Изменения применяются со следующего ответа.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with Mistral, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Редактируйте в браузере биографию, манеру речи, правила речи и воспоминания персонажа, а также промпт для каждого варианта ИИ, или создайте собственного.\n\nРаботает с Mistral, Local AI и Своим, но не с Convai. Изменения применяются со следующего ответа.",
    -- Prompting page of the character editor (docs/CHARACTER_EDITOR.md)
    ["Custom: {model} at {host}"] = "Свой: {model} на {host}",
    ["Mistral"] = "Mistral",
    ["Local AI, Lite"] = "Local AI, Lite",
    ["Local AI, Standard"] = "Local AI, Standard",
    ["Local AI, Lite, Mature on"] = "Local AI, Lite, для взрослых",
    ["Local AI, Standard, Mature on"] = "Local AI, Standard, для взрослых",
    ["Heading of the output rules"] = "Заголовок правил вывода",
    ["Heading of the example replies"] = "Заголовок примеров ответов",
    ["Heading of the format notes"] = "Заголовок заметок о формате",
    ["Heading of the world and quest context"] = "Заголовок контекста мира и задания",
    ["Heading of what the character remembers"] = "Заголовок того, что помнит персонаж",
    ["Heading of the right-now facts"] = "Заголовок фактов о текущем моменте",
    ["Heading of the character’s own right-now facts"] = "Заголовок собственных текущих фактов персонажа",
    ["Heading of the notes for this turn"] = "Заголовок заметок для этой реплики",
    ["Heading of the things remembered about V"] = "Заголовок того, что помнят о V",
    ["Opening line for a named character"] = "Первая строка для именованного персонажа",
    ["Opening line for an ordinary person"] = "Первая строка для обычного человека",
    ["Closing line"] = "Последняя строка",
    ["Closing line for a speaker with a reply length of its own"] = "Последняя строка для говорящего со своей длиной ответа",
    ["Temperature"] = "Температура",
    ["Top P"] = "Top P",
    ["Repeat penalty"] = "Штраф за повторы",
    ["Longest reply (in tokens)"] = "Самый длинный ответ (в токенах)",
    ["Top K"] = "Top K",
    ["Min P"] = "Min P",
    ["Presence penalty"] = "Штраф за присутствие",
    ["Frequency penalty"] = "Штраф за частоту",
    ["Advanced parameters (JSON)"] = "Расширенные параметры (JSON)",
    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "Дополнительные настройки, которые добавляются к каждому ответу, в виде объекта JSON, например {example}. Используйте их для сэмплеров, для которых нет поля выше. Настройка, для которой есть своё поле выше, отклоняется. Если сервер отклоняет настройку, она пропускается, а ответ всё равно приходит.",
    ["Mistral takes only the settings shown here. Top K, Min P and the advanced JSON are for Local AI and Custom models."] = "Mistral принимает только настройки, показанные здесь. Top K, Min P и расширенный JSON предназначены для моделей Local AI и своих моделей.",
    ["Mistral does not take this setting."] = "Mistral не принимает эту настройку.",
    ["That is not valid JSON."] = "Это некорректный JSON.",
    ["This must be a JSON object, for example {example}."] = "Это должен быть объект JSON, например {example}.",
    ["Too many keys. Keep {max} or fewer."] = "Слишком много ключей. Оставьте не более {max}.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}” нельзя использовать как имя ключа. Используйте буквы, цифры и символы подчёркивания.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}” имеет собственную настройку в этой форме. Используйте её.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "Для длины ответа используйте поле «Самый длинный ответ», а не “{name}”.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}” задаётся модом и здесь не может быть изменён.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "“{name}” требует число, текст, true или false либо список таких значений.",
    ["Longest character description, in characters"] = "Самое длинное описание персонажа, в символах",
    ["Earlier turns kept"] = "Сохранено обменов",
    ["Right-now sentence"] = "Фраза о текущем моменте",
    ["Notes for this turn"] = "Заметки для этой реплики",
    ["That prompting option was not found."] = "Этот вариант промпта не найден.",
    ["Keep at least one rule."] = "Оставьте хотя бы одно правило.",
    ["Rule {n} is empty. Write the rule or delete it."] = "Правило {n} пустое. Напишите правило или удалите его.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "Правило {n} слишком длинное. Держите каждое короче {max} символов.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "Правила вместе слишком длинные. Держите их в сумме короче {max} символов.",
    ["This text is too long. Keep it under {max} characters."] = "Текст слишком длинный. Держите его короче {max} символов.",
    ["This text cannot be empty."] = "Текст не может быть пустым.",
    ["Use a number from {min} to {max}."] = "Введите число от {min} до {max}.",
    ["Too many stop texts. Keep {max} or fewer."] = "Слишком много стоп-текстов. Оставьте не более {max}.",
    ["A stop text is too long. Keep each one under {max} characters."] = "Один стоп-текст слишком длинный. Держите каждый короче {max} символов.",
    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "Сейчас в работе",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Как отвечает каждый вариант беседы. У каждого варианта свой промпт. Изменение учитывается со следующей реплики, перезапуск не нужен.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Факты, которые персонажи получают из игры, и короткий список фильтров безопасности здесь редактировать нельзя. Промпт Convai хранится на стороне Convai.",
    ["Mistral and Local AI"] = "Mistral и Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite и Standard — два размера модели Local AI. Вариант «для взрослых» используется, пока включён контент для взрослых.",
    ["Your Custom models and APIs"] = "Ваши собственные модели и API",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Собственная модель появится здесь, когда вы выберете «Свой» в качестве поставщика бесед и укажете модель.",
    ["From {min} to {max}."] = "От {min} до {max}.",
    ["Shipped: {value}"] = "Как в игре: {value}",
    ["Rule {n}"] = "Правило {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Правило {n}, для говорящего со своей длиной ответа",
    ["Rule {n}, for Mature content"] = "Правило {n}, для контента для взрослых",
    ["Move rule {n} up"] = "Правило {n} вверх",
    ["Move up"] = "Вверх",
    ["Move rule {n} down"] = "Правило {n} вниз",
    ["Move down"] = "Вниз",
    ["Delete rule {n}"] = "Удалить правило {n}",
    ["Other versions of this rule"] = "Другие версии этого правила",
    ["Leave a version empty to use the rule text."] = "Оставьте версию пустой, чтобы использовать текст правила.",
    ["For a speaker with a reply length of its own"] = "Для говорящего со своей длиной ответа",
    ["For Mature content"] = "Для контента для взрослых",
    ["Shipped: off"] = "Как в игре: выкл.",
    ["Shipped: the mod’s own limit"] = "Как в игре: собственный лимит мода",
    ["before V’s words"] = "перед словами V",
    ["after V’s words"] = "после слов V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Повторить фразу «где вы» прямо перед словами V",
    ["The notes for this turn go"] = "Заметки для этой реплики пойдут",
    ["Output rules"] = "Правила вывода",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Пронумерованные правила, которые модель читает перед каждым ответом. Используйте {name} для имени персонажа и {words} для длины ответа говорящего, у которого она есть.",
    ["Example replies"] = "Примеры ответов",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Ответы, которые модель видит после правил. Маленькая модель может скопировать их слово в слово, поэтому либо не добавляйте ни одного, либо делайте их короткими и простыми.",
    ["Add an example reply"] = "Добавить пример ответа",
    ["An example reply"] = "Пример ответа",
    ["Example reply {n}"] = "Пример ответа {n}",
    ["Opening line"] = "Первая строка",
    ["The first line of the character text. Use {name} for the character’s name."] = "Первая строка текста персонажа. Используйте {name} для имени персонажа.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "Последнее, что модель читает перед ответом. Используйте {name} для имени персонажа и {words} для длины ответа. Настройка контента для взрослых добавляет после этого свою фразу.",
    ["Section headings"] = "Заголовки разделов",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Заголовки, которые отмечают каждую часть промпта. Меняйте формулировки, но не порядок.",
    ["Layout"] = "Разметка",
    ["Where some notes go in the prompt."] = "Где в промпте стоят некоторые заметки.",
    ["Sampling"] = "Выборка",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "Насколько свободно модель подбирает слова ответа. Оставьте поле пустым, чтобы использовать значение из игры.",
    ["Length limits"] = "Ограничения длины",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Сократите то, что читает модель, — ответы будут быстрее. Ограничения мода всё равно действуют, поэтому эти настройки могут только сокращать.",
    ["Stop texts"] = "Стоп-тексты",
    ["Mature layer"] = "Слой для взрослых",
    ["The crude, forward wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Грубые, прямые формулировки, которые добавляются, когда включён Контент для взрослых. Мод выбирает откровенную или намекающую версию строки в зависимости от того, что разрешает загруженная модель, поэтому редактируйте ту версию, которую использует ваша модель. Пустое поле убирает эту строку. Строка только для взрослых и жёсткие ограничения всегда добавляются в конце и не редактируются.",
    ["Speech line"] = "Строка речи",
    ["Word bank"] = "Словарь слов",
    ["Romance line"] = "Строка о романтике",
    ["Closing clause"] = "Заключительная фраза",
    ["Tone line"] = "Строка тона",
    ["Partner paragraph: affection and desire"] = "Абзац о партнёре: привязанность и желание",
    ["Partner paragraph: nothing invented"] = "Абзац о партнёре: ничего не выдумывать",
    ["{part}, for models that allow explicit sex"] = "{part}, для моделей, которые допускают откровенный секс",
    ["{part}, for models that keep sex suggestive"] = "{part}, для моделей, которые оставляют секс намёком",
    ["This option does not get the Mature layer."] = "Этот вариант не получает слой для взрослых.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "Слой для взрослых и последняя строка, для моделей, которые допускают откровенный секс",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "Слой для взрослых и последняя строка, для моделей, которые оставляют секс намёком",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "Ответ заканчивается, когда модель пишет один из них. Переносы строк считаются. До {max}.",
    ["Add a stop text"] = "Добавить стоп-текст",
    ["A text that ends the reply"] = "Текст, который завершает ответ",
    ["Stop text {n}"] = "Стоп-текст {n}",
    ["Preview"] = "Просмотр",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "Текст промпта так, как его читала бы модель для примерного персонажа. Он следует за вашими правками по мере ввода, ещё до сохранения.",
    ["Sample character name"] = "Имя примерного персонажа",
    ["A speaker with a reply length of its own"] = "Говорящий со своей длиной ответа",
    ["Reply length in words"] = "Длина ответа в словах",
    ["Mature content is on"] = "Контент для взрослых вкл.",
    ["The preview waits until the problems in the form are fixed."] = "Предпросмотр ждёт, пока будут исправлены ошибки в форме.",
    ["No example replies."] = "Нет примеров ответов.",
    ["No closing line."] = "Нет последней строки.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "Вернуть исходный промпт для {name}? Ваши изменения в этой части будут удалены.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "Вернуть исходный промпт для {name}? Все ваши изменения в нём будут удалены.",
    ["Back to the shipped prompting."] = "Вернуть исходный промпт.",
    ["Prompting"] = "Промпт",
    ["Street reputation"] = "Уличная репутация",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Банды, NCPD, корпорации и жители каждого района помнят, что сделал V: Street Cred, решения в заказах, драки, преступления на глазах полиции и то, как ты обращаешься с людьми. От этого зависят приветствие, доверие и помощь.\n\nТолько обычные люди, не именные и не сюжетные персонажи. Меняет их слова, ничего в игре.",
    ["NPCs react to threats and commands"] = "NPC реагируют на угрозы и приказы",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "Обычные люди, которым ты угрожаешь, убегают, сжимаются от страха или дают отпор, как свойственно их типу: члены банд и охранники отвечают на оскорбление кулаками, а на угрозу смерти оружием.\n\nОни также могут сделать то, что ты им скажешь, если сделали бы: лечь на землю, остановиться или выйти из машины.\n\nТолько обычные люди, никогда персонажи с именем или из сюжета, и никогда во время сцен, заданий или боёв.",
    ["Voice language"] = "Язык голоса",
    ["English"] = "английский",
    ["Automatic"] = "Авто",
    ["Polish"] = "польский",
    ["Russian"] = "русский",
    ["Ukrainian"] = "украинский",
    ["Turkish"] = "турецкий",
    ["Czech"] = "чешский",
    ["Hungarian"] = "венгерский",
    ["Japanese"] = "японский",
    ["Korean"] = "корейский",
    ["Chinese"] = "китайский",
    ["Choose one of the listed reply languages."] = "Выберите один из перечисленных языков ответа.",
    ["The language the characters speak. Counts only while Voice playback is on; with it off, replies follow what you write.\n\nAutomatic: follows what you write or say, and never changes on a short line.\n\nA voice that cannot speak the language shows the reply as text."] = "Язык, на котором говорят персонажи. Учитывается, только когда включено озвучивание ответов; если оно выключено, ответы следуют за тем, что вы пишете.\n\nАвто: следует за тем, что вы пишете или говорите, и никогда не меняется на короткой реплике.\n\nГолос, который не может говорить на этом языке, показывает ответ текстом.",
    ["No speech was heard. Hold the talk key while you speak."] = "Речь не услышана. Удерживайте клавишу голоса, пока говорите.",
    ["Voice activation"] = "Голосовая активация",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "Голосовой активации не удалось открыть микрофон. Проверьте устройство ввода в Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "Голосовой ввод не смог подключиться к Convai. Удерживайте клавишу голоса ещё раз или введите текст.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Говорите без удержания клавиши. Когда вы смотрите на персонажа или рядом спутник, мод слушает и отвечает, если вы делаете паузу около секунды.\n\nНикогда во время собственных сцен и выбора реплик или пока говорит персонаж. С вашего ПК ничего не уходит, пока не услышана речь. Лучше наушники; микрофон Bluetooth-гарнитуры переводит их в режим разговора на время прослушивания.",
    ["Opening microphone…"] = "Открытие микрофона…",
    ["Speak now"] = "Говорите сейчас",
    ["Controller talk button"] = "Кнопка разговора на геймпаде",
    ["Talk with a controller: hold the left stick click (L3) at a character, speak, and let go to send. Hold it with the stick at rest.\n\nOn foot only, never in menus, scenes, dialogue choices, calls, combat or a vehicle. The click still toggles sprint, which does nothing while you stand."] = "Разговор с геймпадом: зажмите нажатие на левый стик (L3) на персонаже, говорите и отпустите, чтобы отправить. Удерживайте, пока стик в покое.\n\nТолько пешком, никогда в меню, сценах, вариантах реплик, звонках, бою или в транспорте. Нажатие всё равно переключает спринт, который на месте ничего не даёт.",
    ["V speaks your microphone lines"] = "Голос V для речи в микрофон",
    ["After you speak (hold to talk or Voice activation), V says your words out loud in V’s voice, and the reply follows V’s line. Needs V’s voice on. Off by default, because you just said it yourself."] = "После того как ты заговоришь (удерживай, чтобы говорить, или Голосовая активация), V произносит твои слова вслух голосом V, а ответ идёт после реплики V. Нужно, чтобы голос V был включён. По умолчанию выключено, потому что эти слова уже прозвучали.",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Введите текст в поле поиска, чтобы найти модель по имени или записи, например «rita wheeler». Достаточно части слова.",
    ["Content packs"] = "Наборы контента",
    ["Add-ons that change how the characters talk."] = "Дополнения, которые меняют манеру речи персонажей.",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Mistral, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Включает или выключает набор контента {name}. Набор меняет то, как говорят персонажи. Его изменения промпта работают с Mistral, Local AI и Свой. В Convai действуют его правила мира и собственные персонажи Convai. Переключатель действует со следующего ответа, новые имена — после перезапуска.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Наборы контента добавляют правила после ваших. Здесь их нельзя изменить: выключите набор в игре в разделе Настройки > Наборы контента.",
    ["From the content pack {name}"] = "Из набора контента {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Наборы контента, которые меняют этот промпт: {names}. Ваши изменения остаются поверх их, а Сбросить до стандартного возвращает формулировку набора.",
    ["Memory in use"] = "Используемая память",
    ["Normal memory"] = "Обычная память",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Удалить воспоминания очищает только память, показанную здесь. Другая память остаётся без изменений.",
    ["This clears the memory in use: {memory}."] = "Это очистит используемую память: {memory}.",
    ["Backspace"] = "Backspace",
    ["Cancelled."] = "Отменено.",
    ["Caps lock"] = "Caps Lock",
    ["Choose a key or a controller button."] = "Выберите клавишу или кнопку геймпада.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Выберите клавиши и кнопки геймпада для разговора голосом или текстом, групповых чатов и управления напарниками. Они работают сразу.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Выберите клавиши и кнопки геймпада для действий мода. Нажмите «Задать», затем нужную клавишу или кнопку. Esc или B отменяет выбор. Изменение работает сразу, а клавиши, назначенные в Cyber Engine Tweaks, продолжают работать. Выбирайте клавиши, которые игра не использует.",
    ["Controller"] = "Геймпад",
    ["Controller {button}"] = "Геймпад: {button}",
    ["D-pad down"] = "Крестовина вниз",
    ["D-pad left"] = "Крестовина влево",
    ["D-pad right"] = "Крестовина вправо",
    ["D-pad up"] = "Крестовина вверх",
    ["Down arrow"] = "Стрелка вниз",
    ["End"] = "End",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Групповой текстовый чат",
    ["Group voice chat"] = "Групповой голосовой чат",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Удерживайте, чтобы говорить со всеми персонажами рядом сразу, и отпустите, чтобы отправить. Если ни на кого не смотреть, вы говорите с первым членом вашей группы и ещё с двумя членами группы.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Удерживайте, чтобы говорить с Джонни, голосом в вашей голове, куда бы вы ни смотрели, и отпустите, чтобы отправить. Для этого в Настройках должен быть включён параметр «Джонни в вашей голове».",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Удерживайте клавишу или кнопку, пока говорите, и отпустите, чтобы отправить, как клавишу разговора в Cyber Engine Tweaks. Если ни на кого не смотреть, вы говорите с первым членом вашей группы.",
    ["Home"] = "Home",
    ["Insert"] = "Insert",
    ["Key bindings"] = "Назначение клавиш",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Для назначения клавиш нужен Codeware, а его в этой игре нет. Откройте «Справку», чтобы узнать, что отсутствует.",
    ["Key or button"] = "Клавиша или кнопка",
    ["Left arrow"] = "Стрелка влево",
    ["Menu"] = "Меню",
    ["No key was pressed, so nothing changed."] = "Клавиша не нажата, поэтому ничего не изменилось.",
    ["Not available"] = "Недоступно",
    ["Not set"] = "Не задано",
    ["Num lock"] = "Num Lock",
    ["Page down"] = "Page Down",
    ["Page up"] = "Page Up",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Нажмите сюда, затем нужную клавишу или кнопку геймпада. Esc или B отменяет выбор. Работает сразу.",
    ["Press it to open the Companion Manager while you play."] = "Нажмите, чтобы открыть управление напарниками во время игры.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Нажмите, чтобы написать персонажу, на которого вы смотрите. Если ни на кого не смотреть, вы пишете первому члену вашей группы.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Нажмите, чтобы написать Джонни, голосу в вашей голове, куда бы вы ни смотрели. Для этого в Настройках должен быть включён параметр «Джонни в вашей голове».",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Нажмите, чтобы сразу написать всем персонажам рядом. Если ни на кого не смотреть, вы пишете первому члену вашей группы и ещё двум членам группы.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Нажмите клавишу или кнопку геймпада для действия «{action}». Esc или B отменяет выбор.",
    ["Print screen"] = "Print Screen",
    ["Remove the key or button you set here."] = "Удалите клавишу или кнопку, назначенную здесь.",
    ["Right arrow"] = "Стрелка вправо",
    ["Scroll lock"] = "Scroll Lock",
    ["Space"] = "Пробел",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Разговор текстом",
    ["Talk by voice"] = "Разговор голосом",
    ["Talk to Johnny by text"] = "Разговор с Джонни текстом",
    ["Talk to Johnny by voice"] = "Разговор с Джонни голосом",
    ["That key is already used for another action."] = "Эта клавиша уже назначена на другое действие.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Не удалось загрузить назначение клавиш мода. Откройте «Справку», чтобы узнать, что не так.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Скрипты мода не загрузились, поэтому назначить клавишу нельзя. Откройте «Справку», чтобы узнать, что не так.",
    ["The same setting as Settings > Voices > Controller talk button."] = "Та же настройка, что и «Настройки > Голоса > Кнопка разговора на геймпаде».",
    ["Up arrow"] = "Стрелка вверх",
    ["View"] = "Просмотр",
    ["{action} cleared."] = "Назначение «{action}» очищено.",
    ["{action} is set to {key}."] = "«{action}» назначено на {key}.",
    ["{key} is already used for {other}. Choose another."] = "Клавиша {key} уже используется для «{other}». Выберите другую.",
    ["10 minutes"] = "10 минут",
    ["2 minutes"] = "2 минуты",
    ["5 minutes"] = "5 минут",
    ["Cancel this meeting. She is not told."] = "Отменить встречу. Она не узнает.",
    ["Car"] = "Машина",
    ["Choose how long she waits."] = "Выберите, сколько она ждёт.",
    ["Choose how she arrives."] = "Выберите, как она приедет.",
    ["Choose one of the listed options."] = "Выберите один из вариантов.",
    ["Choose when she arrives."] = "Выберите, когда она приедет.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Напарники приходят к вам, когда вы их приглашаете: пешком или на машине, пишут, ждут и помнят, если вы так и не пришли.\n\nПо умолчанию выключено.",
    ["Fine. Call me when you know what you want."] = "Ладно. Позвони, когда решишь, чего хочешь.",
    ["How long she waits"] = "Сколько она ждёт",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Сколько она ждёт вас после прибытия прямо сейчас. После прибытия по таймеру она ждёт столько, сколько выбрана задержка. Ожидание прекращается во время боя, сцены или меню.",
    ["How she arrives"] = "Как она приезжает",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Я ждала {minutes} минут в {place}, а ты так и не пришёл. Забудь.",
    ["I'm here at {place}. Where are you?"] = "Я на {place}. Ты где?",
    ["Immersive invitations"] = "Иммерсивные приглашения",
    ["In 10 minutes"] = "Через 10 мин",
    ["In 2 minutes"] = "Через 2 мин",
    ["In 5 minutes"] = "Через 5 мин",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Пригласите напарника, и она правда придёт к вам: появится вне поля зрения, придёт пешком или приедет на машине, напишет, когда будет на месте, и будет ждать вас.",
    ["Meet at my waypoint when I ask"] = "Встречаться у моей метки по просьбе",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Выкл.: «Пригласить» сразу приводит напарника к вам.\n\nВкл.: напарник, которого вы пригласили кнопкой «Пригласить», во вкладке «Контакты» или сообщением, идёт к вам и приходит через время, выбранное здесь. Она пишет, когда на месте, ждёт и уходит сердитой (и помнит это), если вы так и не придёте.",
    ["Right now"] = "Сейчас",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Сейчас: она выходит, как только будет готова.\n\nЧерез 2, 5 или 10 минут: реальные минуты игры, так что она придёт в это время. Потом ждёт столько же, сколько задержка.",
    ["She texts you"] = "Она пишет вам",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Она пишет, когда приходит, когда вы отменяете и когда сдаётся. Выкл.: без сообщений (она всё равно помнит, что её бросили).",
    ["Something came up and I can't make it. Sorry."] = "Что-то случилось, я не смогу. Извини.",
    ["Walk"] = "Пешком",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "Пешком: она появляется вне вашего поля зрения и идёт к вам.\n\nМашина: если рядом дорога, она подъезжает, останавливается на дороге, выходит и идёт остаток пути пешком. Без дороги идёт пешком. Машина остаётся рядом для поездки и исчезает, когда она покидает вашу группу или вы оба уходите от неё далеко.",
    ["When she arrives"] = "Когда она приходит",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Если вы просите её прийти к вашей метке и метка на карте установлена, она идёт туда и сообщает об этом. Выкл.: она всегда приходит туда, где вы.",
    ["Your position cannot be read yet."] = "Пока невозможно определить ваше местоположение.",
    ["on her way"] = "в пути",
    ["the meeting spot"] = "место встречи",
    ["waiting at {place}"] = "ждёт в {place}",
    ["{name} is already on the way."] = "{name} уже в пути.",
    ["{name} is on her way."] = "{name} в пути.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} в пути. Примерно {minutes} мин.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Рада тебя видеть. Поехали.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Пусть съедет",
    ["That companion is not available."] = "Этот напарник недоступен.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "У тебя нет этой квартиры.",
    ["at home"] = "дома",
    ["out"] = "не дома",
    ["with you"] = "с тобой",
    ["{count} more housemates"] = "ещё {count} соседей по квартире",
    ["{name} has moved out."] = "{name} больше не живёт у тебя.",
    ["{name} is back at home."] = "{name} снова дома.",
    ["{name} joins you."] = "{name} присоединяется к тебе.",
    ["{name} moves into {apartment}."] = "{name} переезжает в {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} теперь живёт в {apartment} и остаётся в вашей группе, пока не отправится домой.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} больше не живёт у тебя. Всё остальное остаётся как было.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · живёт в {apartment} · {state}",
    ["Companions change outfits"] = "Напарники меняют наряд",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Напарники из вашей группы время от времени меняют наряд: другой образ днём и ночью, а дома — повседневную одежду, если она есть у персонажа.\n\nТолько когда вы на них не смотрите, никогда на виду, и только для собственных копий вашей группы, никогда для персонажей самой игры. Если выключить эту опцию, они останутся в том, что носят сейчас.",
    ["Choose how often companions speak up."] = "Выберите, как часто спутники подают голос.",
    ["Companions speak up"] = "Спутники подают голос",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Как себя чувствует V по данным других модов, если они установлены: например, усталость, голод, жажда, нервы и зависимости из Dark Future. А также то, что V видимо носит, пока включён наряд из Equipment-EX, чтобы персонажи описывали наряд, а не скрытую под ним одежду.\n\nПо умолчанию выключено. Выкл.: ничего не отправляется, и из этих модов ничего не читается.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Сколько времени прошло с последнего разговора V с этим персонажем, в игре и в реальных днях: с прошлой ночи или несколько дней назад. Говорится только тогда, когда пауза достаточно долгая, и не повторяется в том же разговоре.\n\nВыкл.: ничего не отправляется, и мод перестаёт читать игровые часы для этого.",
    ["Music and TV"] = "Музыка и TV",
    ["Other mods’ state"] = "Состояние других модов",
    ["Speaks up normally"] = "Подаёт голос обычно",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Песня, которая играет на автомобильном радио, когда V едет с персонажем, или на карманном радио V, а также то, что показывают на телевизоре рядом с V.\n\nВыкл.: ничего не отправляется, и мод перестаёт читать это из игры.",
    ["Time since last talk"] = "Время с последнего разговора",
    ["Companions in your party sometimes start talking on their own: now and then at a calm moment, and after a scene or a conversation they were part of. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often: about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Спутники в вашей команде иногда сами начинают говорить: время от времени в спокойный момент и после сцены или разговора, в котором они участвовали. Никогда во время боя, сцен, звонков или в меню.\n\nРедко: около 2 за час игры. Обычно: около 4. Часто: около 6.\n\nКогда Johnny тоже подаёт голос, обе частоты складываются, и говорят они по очереди.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand отвечает на клавиши «Разговор с Джонни» как голос в голове V, когда сюжет его туда помещает. Назначьте клавишу «Разговор с Джонни» на странице «Назначение клавиш»: по умолчанию не назначена.\n\nВкл.: отвечает, когда с ним говорят. Редко: он подаёт голос сам, около 2 раз в час. Обычно: около 4. Часто: около 6.\n\nЕсли спутники тоже подают голос, частоты складываются и говорят по очереди.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Выберите, какую живую информацию об игре передавать персонажам, например место, время, погоду, спутников, здоровье, деньги, снаряжение, задания, музыку и TV и состояние других модов.\n\nПо умолчанию всё включено, кроме состояния других модов, оно выключено. Выключенный вид не отправляется ни одному провайдеру разговоров.",
    ["Housemates"] = "Соседи по квартире",
    ["Housemates talk to each other"] = "Соседи разговаривают друг с другом",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Когда двое или больше соседей дома с вами, они время от времени разговаривают друг с другом.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Персонажи, которым вы говорите, что они могут остаться у вас, переезжают в ваши квартиры и живут там.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Персонажи, которым вы говорите, что они могут остаться у вас, переезжают в ваши квартиры и живут там.\n\nПо умолчанию выключено.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Вкл.: персонажи, которым вы говорите, что они могут остаться у вас, переезжают в ваши квартиры и живут там, и вы можете взять их с собой.\n\nВыкл.: ничего из этого не работает. При выключении они съезжают из ваших квартир, но запоминается, кто там жил, поэтому при включении они возвращаются.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "код OmniVoice не смог загрузиться",
    ["PyTorch is not installed in it"] = "PyTorch не установлен в нём",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Ваш собственный Python (omni-python.txt) проходит тестирование. Откройте эту страницу снова через минуту.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Ваш собственный Python (omni-python.txt) проверяется, когда запускается OmniVoice или когда эта страница проверяет снова.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Ваш собственный Python (omni-python.txt) запускает OmniVoice с {backend} на {card}. Экспериментально.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Ваш собственный Python (omni-python.txt) не использовался: {reason}. OmniVoice использует Python Runtime, которому требуется карта NVIDIA.",
    ["a test on the graphics card failed"] = "тест на видеокарте не пройден",
    ["it did not start or did not answer in time"] = "он не запустился или не ответил вовремя",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "его PyTorch не нашёл видеокарту (без CUDA или ROCm)",
    ["the OmniVoice pack is not installed"] = "пакет OmniVoice не установлен",
    ["the file does not name a python.exe that exists"] = "файл не указывает на существующий python.exe",
    ["the module {module} is missing in it"] = "модуль {module} отсутствует в нём",
    ["OmniVoice on AMD: experimental"] = "OmniVoice на AMD: экспериментально",
    ["{voice} · AMD experimental"] = "{voice} · AMD, экспериментально",
    ["Your AMD Radeon card can run OmniVoice with your own Python and AMD’s ROCm PyTorch. Experimental. Steps: docs/OMNIVOICE_AMD.md in the mod’s repository (github.com/alystria-ai/ai-npc-cyberpunk-mod). Until it is set up, OmniVoice will not start here. Choose Pocket to hear voices."] = "Твоя видеокарта AMD Radeon может запускать OmniVoice с твоим собственным Python и ROCm PyTorch от AMD. Экспериментально. Шаги: docs/OMNIVOICE_AMD.md на странице мода в GitHub (alystria-ai/ai-npc-cyberpunk-mod). Пока это не настроено, OmniVoice здесь не запустится. Выбери Pocket, чтобы слышать голоса.",
    ["Your AMD Radeon card ({card}) can run OmniVoice with your own Python and AMD’s ROCm PyTorch. Experimental. Steps: docs/OMNIVOICE_AMD.md in the mod’s repository (github.com/alystria-ai/ai-npc-cyberpunk-mod). The mod downloads nothing for it."] = "Твоя видеокарта AMD Radeon ({card}) может запускать OmniVoice с твоим собственным Python и ROCm PyTorch от AMD. Экспериментально. Шаги: docs/OMNIVOICE_AMD.md на странице мода в GitHub (alystria-ai/ai-npc-cyberpunk-mod). Мод ничего для этого не скачивает.",
    ["1 minute"] = "1 минута",
    ["2 people"] = "2 человека",
    ["3 people"] = "3 человека",
    ["4 people"] = "4 человека",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Все персонажи, которые живут в твоем доме, съезжают одновременно, из всех квартир. Члены группы, которые там не живут, не затрагиваются. Сосед по квартире, который с тобой, остается в твоей группе.",
    ["Evict"] = "Пусть съедет",
    ["Evict all housemates"] = "Пусть съедут все соседи по квартире",
    ["Housemates in one chat"] = "Соседи по квартире в одном чате",
    ["Housemates moved out: {count}"] = "Соседи по квартире съехали: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Как долго соседи по квартире молчат после чата, прежде чем могут начать другой. Параметр Спутники подают голос по-прежнему ограничивает, сколько чатов приходит в час.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Сколько соседей по квартире присоединяются к одному чату, когда столько людей дома рядом друг с другом. Они говорят по одному. С меньшим количеством дома чат может быть как можно больше.",
    ["Move-in apartment"] = "Квартира для переезда",
    ["Nobody lives at your place."] = "У тебя никто не живет.",
    ["Pause between chats"] = "Пауза между чатами",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Где персонаж переезжает, когда ты говоришь, что может остаться, но не называешь квартиру и не стоишь в одной из своих.\n\nСпроси меня: она спрашивает, какую. Иначе она берет квартиру, которую ты выбираешь здесь. Указаны только квартиры, которыми ты владеешь.",
    ["Ask me"] = "Спроси меня",
    ["Could not start"] = "Не удалось запустить",
    ["Did not start"] = "Не запустилось",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Если папка есть, в самом новом логе в red4ext/logs указано, почему RED4ext её не загрузил: антивирус удалил файл или нет Visual C++ runtime.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Сначала загрузите сохранение. Клавишу можно назначить только при загруженной игре.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Нажатие клавиши до мода не дошло, поэтому ничего не изменилось. Если клавиши не работают из этого меню, назначьте клавишу в разделе назначения клавиш Cyber Engine Tweaks: это работает так же.",
    ["Runtime incomplete"] = "Runtime неполный",
    ["Runtime not loaded"] = "Runtime не загружен",
    ["Service not running ({reason})"] = "Служба не запущена ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkMod says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Плагин Runtime загружен, но служба бесед в этой сессии не оставила следов. В launcher.log в red4ext/plugins/AiNpcCyberpunkMod написано почему: launcher.ini отключён, Node не найден или Node заблокирован программой безопасности. Исправьте это и перезапустите игру.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Служба бесед не видит папку этого мода в игре: виртуальные папки менеджера модов или папку, которую ей не разрешено читать. Распакуйте Runtime прямо в папку Cyberpunk 2077 или запускайте игру из менеджера модов, в котором лежит Runtime.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Служба бесед была запущена, но так и не ответила. Вероятно, программа безопасности сразу её остановила, или Node не может работать на этом ПК. Разрешите red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe в своей программе безопасности и перезапустите игру.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows не позволила игре запустить службу бесед (ошибка {error}). Программа безопасности может блокировать node.exe в red4ext/plugins/AiNpcCyberpunkMod/app/node: разрешите его и перезапустите игру.",
    ["Add a server address first."] = "Сначала добавьте адрес сервера.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Три раза спрашивает сервер, кто он, и показывает, доступен ли он, как быстро отвечает и его версию. Речь не отправляется.",
    ["Connected. The server speaks with {voice}."] = "Подключено. Сервер говорит голосом {voice}.",
    ["Custom voices"] = "Пользовательские голоса",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Удаляет сохранённый адрес сервера. Для речи Удалённому OmniVoice он нужен.",
    ["It answers in {ms} ms."] = "Отвечает за {ms} мс.",
    ["Its voice runs on {device}."] = "Его голос работает на {device}.",
    ["Loading"] = "Загрузка",
    ["Not connected. Replies show as text until the server answers."] = "Не подключено. Ответы показываются текстом, пока сервер не ответит.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "По этому адресу никто не ответил. Проверьте, запущен ли сервер, верны ли адрес и порт и находятся ли оба ПК в одной сети. Сервер, запущенный с настройками по умолчанию, слушает только свой ПК: запустите его с адресом прослушивания 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Выключено. OmniVoice работает на этом ПК.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Включено, но адрес сервера не сохранён. OmniVoice пока не может говорить.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Включено, но адрес сервера не сохранён. Пока вы не добавите адрес, используется Pocket.",
    ["On, but no server address is saved. The server is not used yet."] = "Включено, но адрес сервера не сохранён. Сервер пока не используется.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Включено, но в «Голоса напарников» выбран облачный голос, поэтому сервер не используется.",
    ["On. Waiting for the conversation service."] = "Включено. Ожидание службы разговоров.",
    ["Paste address"] = "Вставить адрес",
    ["Remote OmniVoice"] = "Удалённый OmniVoice",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Выводить голоса на другом ПК или видеокарте с сервером OmniVoice, чтобы этот ПК сохранял частоту кадров.\n\nВключите, нажмите «Применить» и добавьте адрес сервера ниже. Сервер затем озвучивает каждый выбор Pocket или OmniVoice в «Голоса напарников»; облачный голос остаётся выбранным. Если сервер недоступен, ответы показываются текстом, а мод повторяет попытку каждые несколько секунд.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Выводить голоса OmniVoice на другом ПК или видеокарте, где работает сервер OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Выводить голоса Pocket и OmniVoice на другом ПК или видеокарте: переключатель вкл./выкл., адрес сервера и проверка подключения. Работает независимо от того, какой из этих голосов выбран выше.",
    ["Server address"] = "Адрес сервера",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Что-то ответило, но это не сервер OmniVoice. Проверьте порт.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Запустите сервер OmniVoice на другом ПК. Его окно покажет адрес, например 192.168.1.20:8765. Скопируйте его и выберите «Вставить адрес». Он один раз считывается из буфера обмена и сохраняется на этом компьютере.\n\nНа том же ПК используйте 127.0.0.1:8765. Также можно написать address=192.168.1.20:8765 в файле player-remote-omnivoice.txt в папке службы разговоров.\n\nНичего не отправляется, пока Удалённый OmniVoice не включён и не выбран OmniVoice или пока вы не нажмёте «Проверить».",
    ["Status"] = "Состояние",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Сервер OmniVoice недоступен. Ответы показываются текстом, пока он не ответит. Мод повторяет запрос каждые несколько секунд.",
    ["The clipboard does not hold a server address."] = "В буфере обмена нет адреса сервера.",
    ["The clipboard is empty. Copy the address first."] = "Буфер обмена пуст. Сначала скопируйте адрес.",
    ["The port must be a number from 1 to 65535."] = "Порт должен быть числом от 1 до 65535.",
    ["The server address was removed."] = "Адрес сервера удалён.",
    ["The server answered but could not load its voice. Its window says why."] = "Сервер ответил, но не смог загрузить свой голос. Его окно сообщает причину.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Сервер ответил, но ещё загружает свой голос. Попробуйте через минуту.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Сервер другой версии. Используйте папку сервера и мод из одного выпуска.",
    ["The server is ready."] = "Сервер готов.",
    ["The server refused the request."] = "Сервер отклонил запрос.",
    ["The server took too long to answer."] = "Сервер слишком долго не отвечал.",
    ["Use the address only: no user name, no path, no #."] = "Укажите только адрес: без имени пользователя, пути и #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Укажите адрес, который показывает окно сервера, например 192.168.1.20:8765, без https://.",
    ["Waiting for the server to answer…"] = "Ожидание ответа сервера…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Используется ли сейчас сервер. Проверяется, когда нужен голос, а после сбоя каждые несколько секунд, но никогда во время игры.",
    ["Your own character, made in the character editor."] = "Ваш собственный персонаж, созданный в редакторе персонажей.",
    ["They join as a copy of the model they were made from. They talk with Mistral, Local AI or Custom; with Convai they talk as an ordinary person."] = "Он присоединяется как копия модели, на основе которой создан. Говорит через Mistral, Local AI или Свой; с Convai говорит как обычный человек.",
    ["This character needs Mistral, Local AI or Custom to answer."] = "Чтобы отвечать, этому персонажу нужен Mistral, Local AI или Свой.",
    ["Build for your game"] = "Сборка для вашей игры",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Download the Runtime for game {game} from the mod’s Hugging Face page (the main folder is for game 2.5, the game-2.31 folder is for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Ваша игра — {game}, но Runtime — для игры {runtime}. Скачайте Runtime для игры {game} со страницы мода на Hugging Face (основная папка для игры 2.5, папка game-2.31 для игры 2.31), распакуйте в папку Cyberpunk 2077 поверх текущих файлов и перезапустите игру.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Download the Scripts for game {game} from the mod’s Nexus Mods page (the main file is for game 2.5, the optional file marked for game 2.31 is for game 2.31) and install them over these, then restart the game."] = "Ваша игра — {game}, но Scripts — сборка для игры {scripts}. Скачайте Scripts для игры {game} со страницы мода на Nexus Mods (основной файл для игры 2.5, необязательный файл с пометкой для игры 2.31 — для игры 2.31), установите поверх текущих и перезапустите игру.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Download both for game {game}: the Scripts from the mod’s Nexus Mods page, the Runtime from its Hugging Face page (the main folder is for game 2.5, the game-2.31 folder is for game 2.31). Install them over these, then restart the game."] = "Ваша игра — {game}, но Scripts и Runtime — сборка для игры {scripts}. Скачайте оба для игры {game}: Scripts со страницы мода на Nexus Mods, Runtime со страницы мода на Hugging Face (основная папка для игры 2.5, папка game-2.31 для игры 2.31). Установите поверх текущих и перезапустите игру.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Install the Scripts and the Runtime made for the same game as yours (the Scripts from Nexus Mods, the Runtime from Hugging Face), then restart the game."] = "Scripts — сборка для игры {scripts}, а Runtime — сборка для игры {runtime}, и версия игры не совпадает ни с одной из них. Установите Scripts и Runtime, сделанные для той же игры, что и у вас (Scripts с Nexus Mods, Runtime с Hugging Face), и перезапустите игру.",
    ["The Runtime is for game {other}, yours is {game}. Get the Runtime for {game} from Hugging Face."] = "Runtime — для игры {other}, у вас игра {game}. Получите Runtime для {game} на Hugging Face.",
    ["The Scripts are for game {other}, yours is {game}. Get the Scripts for {game} from Nexus Mods."] = "Scripts — для игры {other}, у вас игра {game}. Получите Scripts для {game} на Nexus Mods.",
    ["This mod is for game {other}, yours is {game}. Get the Scripts and Runtime for {game}."] = "Мод для игры {other}, у вас игра {game}. Получите Scripts и Runtime для {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts — для игры {scripts}, Runtime — для {runtime}. Должны совпадать. См. Справку.",
    ["Choose one of the listed microphones."] = "Выберите один из перечисленных микрофонов.",
    ["Microphone"] = "Микрофон",
    ["The input the mod listens to for the talk key, Voice activation and the controller button.\n\nWindows default follows the input Windows picks. Choose another if the default never hears you, for example when a mixer app routes your microphone elsewhere.\n\nA change counts the next time the microphone opens. A missing input falls back to the default."] = "Вход, который мод слушает для клавиши голоса, Голосовой активации и кнопки геймпада.\n\nWindows по умолчанию следует за входом, который выбирает Windows. Выберите другой, если вас никогда не слышно, например когда микшер направляет микрофон в другое место.\n\nИзменение действует при следующем открытии микрофона. Если выбранного входа нет, используется вход по умолчанию.",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Микрофон, выбранный в настройках ({chosen}), не подключён, поэтому используется вход Windows по умолчанию: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Микрофон, выбранный в настройках, не подключён, поэтому используется вход Windows по умолчанию.",
    ["Windows default"] = "Windows по умолчанию",
    ["not connected"] = "не подключён",
    ["{name}, chosen in Settings > Voices."] = "{name}, выбран в Настройки > Голоса.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, вход Windows по умолчанию. Другой выбирается в Настройки > Голоса > Микрофон.",
}
